programs.sol:
"""Approximate this early-layer signal with small, literal text rules.

Positive cues include unit-test names, escaped punctuation, and comma/quote
boundaries after clause-like English text. Smaller rules cover headings,
five-related spellings, 30/31 (especially dates), tilde-A, and doubled UTF-8
encoding. Line-leading access modifiers and repeated middle dots are negative.

Strengths are training-calibrated estimates, not a token-ID table. Unmatched tokens
predict zero: this intentionally leaves much of the component's lexical
variation unexplained. Keep only a preceding token and 160 characters of text,
resetting both at document boundaries.
"""
import re
import calendar
READS = ()
MONTHS = '|'.join(calendar.month_name[1:] + calendar.month_abbr[1:])
DATE_THREE = re.compile('(?:' + MONTHS + ')\\.?\\s+3$', re.I)
LINE_START = re.compile('^[+\\- ]*\\d*\\s*$')
TEST_CALL = re.compile('(?:\\b(?:it|test|describe|suite)|t\\.Run)(?:\\.(?:only|skip))?$')

def response(s, previous, before, raw=b'', previous_raw=b''):
    word = s.strip()
    prev = previous.strip()
    line = before.rsplit('\n', 1)[-1]
    at_indent = bool(LINE_START.fullmatch(line))
    # Malformed encoding, headings, and endings of quotations.
    if raw == b'\x83' and previous_raw.endswith(b'\xc2') and ('Ã' in before[-8:]):
        return 5.01
    if word == '###':
        if re.search('[A-Za-z0-9],?\\n\\n$', before):
            return 0.26
        return -0.05
    if word in (',”', ',"', ",''") and re.search('[A-Za-z]$', before):
        start = max(before.rfind('“'), before.rfind('"'))
        span = before[start + 1:] if start >= 0 else before
        words = re.findall('[A-Za-z]+', span)
        capitals = sum(w[0].isupper() for w in words[1:])
        if len(words) > 2 and capitals > 0.6 * (len(words) - 1):
            return 0.01
        pronouns = set('i we you he she they it this that don there'.split())
        function_words = set(
            'the a to of in is are was be have has and will can'.split()
        )
        if len(words) >= 8 or (words and words[0].lower() in pronouns):
            return 0.66
        if sum((w.lower() in function_words for w in words)) >= 3:
            return 0.66
        return 0.18
    if word == ',”':
        return 0.53
    if word in (',"', ",''"):
        return 0.0
    if word == '»,':
        return 0.05
    # Unit-test declarations and their first, quoted argument.
    quoted_argument = (word.startswith(('"', "'")) and s[:1].isspace()
                       or word in ("('", '("', '(`'))
    if quoted_argument and TEST_CALL.search(before):
        return 1.53
    if prev == '@test' and word.startswith(('"', "'")):
        return 1.53
    if word in ('Test', 'test', '@Test'):
        if word == '@Test':
            return 0.84
        if prev == '@':
            return 1.49
        if prev == '#[':
            return 1.14
        if prev in ('fn', 'void'):
            return 0.31
        if prev in ('def', 'function', 'func'):
            return 0.91
    if word == '.Run' and prev == 't':
        return 1.2
    if word == '_F' and prev == 'TEST' or (word == 'TEST' and at_indent):
        return 0.9
    if word == 'est' and re.search('(?:vit|supert)$', before):
        return 1.0
    if word in ('it', 'describe', 'test') and at_indent and before:
        return 0.18 if word == 'test' else 0.5
    if word in ('should', 'Should') and re.search('(?:it|test|describe)\\([\\"\\\']$', before):
        return 0.35
    if word == 'void':
        if '@Test' in before or '[Test' in before:
            return 1.08
        return 0.0
    if word in ('public', 'private', 'protected'):
        if at_indent:
            return {'public': -0.53, 'private': -0.26, 'protected': -0.57}[word]
        if word == 'public':
            return -0.06
    # Escaping and shell quotation.
    if '"' in word and '\\' in word:
        if previous.strip() == '\\':
            return 1.7
        if previous.endswith('\\'):
            return 0.86
        if s.startswith(' '):
            if re.search('\\b(?:command|cmd|grep|find|echo|node|sed|bash|python)\\b', before):
                return 0.43
            return 0.03
    escaped = previous.endswith('\\') or word.startswith('\\')
    if '*' in word and (escaped or word.endswith('\\')):
        return 0.7
    if '_' in word and (escaped or word.endswith('\\')):
        if word.endswith('\\') and (not word.startswith('\\')):
            return 0.21
        return 0.39
    if word == '$' and escaped or word in ('\\$',):
        return 0.22
    if word == '|' and escaped:
        return 0.17
    if word and (not word.strip('\\')):
        if len(word) >= 4:
            return 0.72
        if len(word) == 2:
            return 0.1
    if s.startswith(" '"):
        if prev == 'awk':
            return 1.2
        if re.search('\\s-[A-Za-z]$', before):
            return 0.68
    if word == 'EOF' and re.search('<<\\s*[\\\'\\"]?$', before):
        return 1.18
    if word == '3' and before.endswith('\\xa'):
        return 0.78
    if word in ('xc', 'xe') and previous.endswith('\\'):
        return 0.59
    # Smaller character and number-shape effects.
    if word in ('ã', 'Ã'):
        return 1.85
    if word and (not word.strip('·')) and (len(word) > 1):
        return -0.59
    if word.lower() in ('ive', 'ives') and re.search('\\bf$', before, re.I):
        return 1.5
    if word == '3' and re.search('&#$', before):
        return 0.55
    if word.lower() == 'fives':
        return 1.2
    if word.lower() == 'five':
        return 0.3 if word[0].isupper() else 0.11
    if word in ('0', '1') and prev == '3':
        if DATE_THREE.search(before):
            return 0.64 if word == '0' else 0.48
        return 0.25 if word == '0' else 0.12
    if word == '5':
        if prev == '6' and (not re.search('\\d+\\.[0-9]*$', before)):
            return 0.26
        if before and before[-1].isalpha():
            return 0.28
        if re.search('\\d+\\.[0-9]*$', before):
            return -0.07
        return 0.06
    return 0.0

def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, before, previous_raw = ('', '', b'')
    else:
        _, previous, before, previous_raw = carry
    s = prefix.token_strings[-1]
    raw = prefix.token_bytes[-1]
    value = response(s, previous, before, raw, previous_raw)
    return ((doc, s, (before + s)[-160:], raw), value)

programs.haiku:
"""layers.1.mlp.down_proj:4800, predicted by a few readable token-context rules.

This component is quiet almost everywhere (it is above 0.1 causal importance on about
one token in two thousand). Its largest values come from a few recognisable places,
and this program predicts those and treats everything else as zero:

* Test cases, strongest. The opening bracket of a test body, `('` or `("`, right after
  `it`, `test`, `describe` or `suite` (as in `it('should ...`), gets about +2. A test
  name being declared (after `def`, `func`, `fn`, `void`, `function`, `@` or `#[`) gets
  about +0.9. Go's `t.Run(` gets about +1.5.
* A closing quote after a comma in prose, as in `...is ready,” he said`, gets about +0.5.
  A `###` heading after a blank line gets about +0.3.
* Escaped or mis-decoded text gets a small positive value: backslash-escape tokens in
  code strings (about +0.3), byte fragments such as `xc` or `\\xc` (about +0.5), and
  mojibake `ã` (about +1.5).
* Negative: Java/C# member modifiers (`public`, `private`, `protected`, `static`, about
  -0.3), `void` right after `public` (about +0.5, a method's return type),
  and runs of middle dots `··` (about -0.55).

What it leaves out: most of the variance is small, context-dependent wobble on ordinary
tokens such as digits and spaces, whose sign these rules cannot predict. Only the
previous and the current token are read.
"""

READS = ()

TEST_BLOCKS = {"test", "Test", "TEST", "it", "describe", "suite", "specify"}
DECLARED_AFTER = {"def", "func", "fn", "void", "function", "@", "#["}
TEST_OPENERS = {"('", '("', "(`"}
CLOSING_QUOTES_AFTER_COMMA = {',”', ',"'}
ACCESS_MODIFIERS = {"public", "private", "protected", "static"}
MIDDLE_DOTS = {"·", "··", " ·"}
ESCAPED_CODE = {"*\\", "\\_", "_\\", "\\\\", "\\\\\\\\", "\\$", " \\$", "\\/"}
BYTE_PIECES = {"xc", "xe", "xa", "\\xc", "\\xe"}
MOJIBAKE = {"ã", "Ã"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip()
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if tok in MIDDLE_DOTS:
        value = -0.55
    elif word in TEST_BLOCKS and prev in DECLARED_AFTER:
        value = 0.9
    elif tok in TEST_OPENERS and prev in TEST_BLOCKS:
        value = 2.0
    elif word == "Run" and prev == "t":
        value = 1.5
    elif word == "void" and prev == "public":
        value = 0.5
    elif tok in CLOSING_QUOTES_AFTER_COMMA:
        value = 0.5
    elif word == "###" and prev == "":
        value = 0.3
    elif word in ACCESS_MODIFIERS:
        value = -0.3
    elif tok in ESCAPED_CODE:
        value = 0.3
    elif tok in BYTE_PIECES:
        value = 0.5
    elif tok in MOJIBAKE:
        value = 1.5
    else:
        value = 0.0
    return carry, float(value)

programs.sol:
"""Approximate a capitalization-sensitive component with local typography rules.

Single capital tokens are negative after prose boundaries. Acronym continuations
are weak. Operators and attached identifier punctuation favor positive values,
while an internal CamelCase capital in code favors a negative value. Recent
capital density moderates these rules. Other tokens get zero, except for a small
document-initial bias. State resets at document boundaries.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, recent, position = '', '', 0
    else:
        _, previous, recent, position = carry
    s = prefix.token_strings[-1]
    letters = ''.join(c for c in s if c.isalpha())
    spaced = s[:1].isspace()
    value = 0.0
    if position == 0:
        if letters:
            value = 0.35 if letters[0].isupper() else 0.06
            if spaced:
                value = 0.12
        else:
            value = -0.10 if spaced else 0.09
    elif len(letters) == 1 and letters.isupper():
        last = previous.rstrip()[-1:]
        capitals = sum(c.isupper() for c in recent)
        fraction = capitals / max(1, sum(c.isalpha() for c in recent))
        code = '=' in recent
        before = s[:s.find(letters)].strip()
        if code and before and before[-1] in '.([{_$-':
            value = 0.80 if fraction < 0.05 else 0.30
        elif code and not spaced and not before and last.islower():
            value = -0.70
        elif last in ('=', '+', '*', '$', '\\'):
            value = 0.35
        elif last in ('.', '!', '?'):
            if letters == 'I':
                value = -0.42
            elif fraction > 0.24:
                value = -0.32
            elif fraction > 0.10:
                value = -0.57
            else:
                value = -0.85 if letters.isascii() else -0.69
        elif '\n' in previous:
            if code:
                value = 0.35 if previous.isspace() else 0.10
            elif '_' in recent:
                value = -0.27
            else:
                value = -0.43 if letters in ('A', 'I') else -0.67
        elif fraction < 0.005:
            value = -0.08 if spaced else 0.27
        elif last.isupper():
            value = -0.13 if spaced else 0.01
        elif last in ('"', '“', '‘', '«'):
            value = -0.55
        elif last == "'":
            value = -0.04
        elif not code and spaced and last.islower() and letters in ('A', 'I'):
            value = -0.08 if letters == 'I' else -0.12
        elif code:
            value = 0.04
            if '_' in recent:
                value = 0.50 if fraction < 0.033 else 0.17
        elif recent.count('{') + recent.count('}') >= 2:
            value = 0.09
        else:
            value = -0.20
    return (doc, s, (recent + s)[-240:], position + 1), value

"""A 'but'/contrast-marker detector with some literal spelling echoes.

Capitalized 'But' is usually weaker. Punctuation and literal idiom endings
('nothing but', 'no choice but', 'help but') scale lowercase 'but'.
Translations and weaker concessive markers get their own strengths;
ambiguous words such as French 'mais' require matching recent vocabulary.
A few short b-initial spellings also respond, sometimes negatively, even
when they are not connectives. Everything else predicts zero.
"""
import re
from wordfreq import zipf_frequency
from anyascii import anyascii

READS = ()

# Adversative and concessive words, not arbitrary token identifiers.
CONNECTIVES = {
    'pero': 2.2, 'sino': 1.35, 'aber': 1.35, 'sondern': 5.0,
    'maar': 4.5, 'utan': 3.8, 'но': 1.6, 'ale': 0.85,
    'ama': 0.5, 'nhưng': 1.3, 'بل': 4.3, 'لكن': 1.0, 'però': 0.95,
    '但': 1.35, '但是': 1.1, '而': 0.65, '却': 0.43,
    '不过': 0.6, '可是': 0.85, '然而': 0.8,
    'しかし': 0.75, 'だが': 0.85, 'でも': 0.15,
    '하지만': 0.85, '그러나': 0.7, '그런데': 0.8,
    'though': 0.3, 'although': 0.25, 'except': 0.22,
    'nevertheless': 0.3, 'nonetheless': 0.25, 'instead': 0.16,
    'doch': 0.5, 'jedoch': 0.6, 'однако': 0.55,
}
AMBIGUOUS = {
    'ma': ('it',), 'mas': ('pt',), 'mais': ('fr',),
    'men': ('sv', 'nb', 'da'),
}
LANGUAGES = ('en', 'fr', 'it', 'pt', 'es', 'de', 'nl', 'sv', 'nb', 'da')


def language_fits(text, languages):
    text = text.rsplit('<|im_start|>', 1)[-1]
    if text.startswith(('assistant\n', 'user\n')):
        text = text.split('\n', 1)[-1]
    words = re.findall(r'[^\W\d_]+', text.lower())[-12:]
    if not words:
        return False
    scores = {lang: sum(zipf_frequency(w, lang) for w in words)
              / len(words) for lang in LANGUAGES}
    return max(scores[l] for l in languages) > max(
        scores[l] for l in LANGUAGES if l not in languages) + 0.3


def english_but(word, before):
    if word.isupper():
        return 3.4
    if word[0].isupper():
        return 2.2 if before.endswith(',') else 1.65
    if re.search(r'\bno choice$', before, re.I):
        return 0.0
    if re.search(r'\b(nothing|anything|everything|all)$', before, re.I):
        return 1.2
    if re.search(r'\bhelp$', before, re.I):
        return 1.7
    if re.search(r'\bwait$', before, re.I):
        return 2.2
    if before.endswith(','):
        return 2.43
    if before.endswith((';', ':', '—', '–')):
        return 1.65
    if before.endswith(('.', '!', '?', '-', '"', '”', '`')):
        return 2.3
    return 3.4


def spelling_echo(word, token, context):
    # These are literal b-word fragments, not semantic categories.
    # Transliterating also recognizes Cyrillic б + ут (b + ut).
    if not token[:1].isspace() and anyascii(context[-1:]).lower() == 'b':
        continuation = anyascii(word).lower()
        if re.fullmatch(r'uts?', continuation):
            return 7.5
        if continuation == 'ib':
            return -6.0 if not context[-2:-1].isalpha() else -3.7
        if re.fullmatch(r'ikes?', continuation):
            return -9.5
        short_fragments = {'k': -3.4, 'un': 3.0, 'ur': 3.0, 'ump': 3.2}
        return short_fragments.get(continuation, 0.0)
    if re.fullmatch(r'bu(n|r|ry)', word):
        return 2.6
    if re.fullmatch(r'bikes?', word):
        return -4.8
    return 4.0 if word in {'-but', '—but'} else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    context = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip()
    lower, before = word.lower(), context.rstrip()
    if lower == 'but':
        value = english_but(word, before)
    elif lower == 'however':
        value = 0.8 if word[0].isupper() else 0.47
    elif lower == 'yet':
        value = 0.8 if word[0].isupper() else 0.45
    elif lower in AMBIGUOUS and (token[:1].isspace()
                                or not before[-1:].isalpha()):
        value = 0.0
        if language_fits(context, AMBIGUOUS[lower]):
            value = 2.7 if before.endswith(';') else 5.6
            if word[0].isupper():
                value = 3.0
    elif lower in CONNECTIVES:
        value = CONNECTIVES[lower]
        if lower in {'но', 'utan'} and not token[:1].isspace():
            value = 0.0
        elif word[:1].isupper():
            value *= 0.8
    else:
        value = spelling_echo(lower, token, context)
    return (doc, (context + token)[-180:]), value

programs.haiku:
"""Component layers.1.mlp.down_proj:4802 as a "but" detector.

What it does: it fires on the word "but" (and its spelling inside a word, and the
equivalent contrast words in other languages), the way a clause-joining contrast
conjunction does. It is strongest on a lowercase " but" that joins two clauses
(about 2.7 on average; about 2.4 right after a comma, about 3.1 elsewhere), weaker on
a sentence-initial "But" (about 1.6), and weaker still on "however", "yet" and other
hedges. Translations such as "mais", "pero", "sondern", "maar" and "но" also fire.
A "ut" that completes "b"+"ut" inside a word (e.g. "trib|ut|aries") fires strongly.
It goes negative on the word "bike"/"bikes" (about -4 to -6). Everything else
predicts 0.

The program is a lookup of tokens to typical activation values, with a few
context rules. The values are rounded averages from the training rows.
"""
READS = ()

BUT = {" but": 2.7, "but": 3.2, " BUT": 3.4, " But": 1.6, "But": 1.7}
TRANSLATED = {" mais": 2.7, " pero": 2.3, " sondern": 4.8, " maar": 4.5, " mas": 1.5,
              " aber": 1.3, " но": 1.6, " ma": 1.9, " ale": 0.9, " però": 0.9, "但": 1.4, " men": 0.5}
HEDGE = {" However": 0.8, "However": 0.9, " however": 0.5, " yet": 0.5, " Yet": 0.8}
BIKE = {" bike": -4.4, " bikes": -5.2, " Bike": -6.2, " bik": -4.8, " Bik": -4.3}
VALUE = {**BUT, **TRANSLATED, **HEDGE, **BIKE}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    if tok in ("ut", "uts") and prev.lower().endswith("b"):
        return carry, 8.0
    word = "".join(ch for ch in tok if ch.isalpha()).lower()
    if word == "but" and tok not in BUT:
        return carry, 2.7
    if tok == " but" and prev != ",":
        return carry, 3.1
    if tok == " but":
        return carry, 2.4
    return carry, VALUE.get(tok, 0.0)

import re

READS = ()

# Words after which a space is followed by a number in running prose (about 5, between 2 and 3).
APPROX_WORDS = {"about", "between", "approximately", "over", "around"}
# Function words: the space after them is usually weak.
FUNCTION_WORDS = {"of", "at", "with", "on", "is", "are", "was", "be", "the", "to", "in", "for", "from", "by"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    word = prev.strip()
    if tok == " ":
        if word == "":
            return carry, 0.07
        if word in APPROX_WORDS or word in FUNCTION_WORDS:
            return carry, 0.09 if word in FUNCTION_WORDS else -0.2
        if re.fullmatch(r"[A-Z]{2,}", word):
            return carry, 0.67
        if re.fullmatch(r"\W+", word):
            return carry, 0.38
        if word.isdigit():
            return carry, 0.32
        if re.fullmatch(r"[A-Z][a-z]+", word):
            return carry, 0.33
        return carry, 0.37
    if tok == ",":
        if prev.strip().isdigit():
            return carry, -0.30
        if re.fullmatch(r" ?[A-Za-z]+", prev):
            return carry, -0.11
        return carry, -0.16
    return carry, 0.0

programs.sol:
"""Estimate a document-opening signal and a few text-formatting responses.

Opening tokens get a large estimate based on letter/digit/punctuation form,
capitalization, and broad word classes. An initial run of the same token
keeps this estimate: repeating it supplies no different textual context.
Later, tabs after digits (often line numbers), escaped indentation,
nonbreaking spaces, and doubled underscores get smaller positive estimates.
Ordinary in-context text gets zero. Fine differences between individual
words and more complicated contextual effects are deliberately not modeled.
"""
import math
from collections.abc import Mapping

READS = ()
ARTICLES = {'a', 'an', 'the'}
CONJUNCTIONS = {
    'and', 'or', 'but', 'nor', 'so', 'yet', 'if', 'because', 'although',
    'while', 'unless', 'until', 'as', 'since', 'whether', 'though',
}
QUESTIONS = {
    'what', 'when', 'where', 'who', 'whom', 'whose', 'why', 'how', 'which',
}
PRONOUNS = {
    'you', 'he', 'she', 'it', 'we', 'they', 'me', 'him', 'her', 'us', 'them',
    'my', 'your', 'his', 'its', 'our', 'their', 'mine', 'yours', 'ours',
    'hers', 'theirs',
}
CODE_DECLARATIONS = {
    'package', 'import', 'class', 'def', 'function', 'const', 'let', 'var',
    'public', 'private', 'protected', 'static', 'void', 'namespace',
}


def opening(s):
    z = s.strip()
    if s.startswith('<|'):
        return 5.35
    if not z:
        if '\n' in s or '\r' in s:
            return 0.9
        return 4.1
    if z.isdigit():
        return 0.8
    if z.isascii() and z.isalpha():
        if len(z) == 1:
            if z.isupper():
                return 3.4 if s.startswith(' ') else 4.2
            return 5.9 if s.startswith(' ') else 4.9
        if z.isupper():
            return 4.9
        word = z.lower()
        if word in ARTICLES:
            return 7.1 if s.startswith(' ') else 6.4
        if word in CONJUNCTIONS:
            return 5.2
        if word in QUESTIONS:
            return 11.3 if z.istitle() and not s.startswith(' ') else 6.5
        if word in PRONOUNS:
            return 9.4
        if word in CODE_DECLARATIONS:
            return 4.0
        if z.istitle():
            return 6.8 if s.startswith(' ') else 8.6
        return 7.6 if s.startswith(' ') else 7.0
    if z.isalpha():
        return 4.9 if len(z) == 1 else 5.8
    if any(c.isalpha() for c in z):
        return 5.1
    return 3.4


def step(carry, prefix, upstream: Mapping):
    s = prefix.token_strings[-1]
    token = prefix.token_ids[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        initial, first, previous, before = True, token, '', ''
    else:
        _, initial, first, previous, before = carry
        initial = initial and token == first

    if initial:
        value = opening(s)
    elif '\t' in s:
        if previous[-1:].isdigit():
            if '\n' in s:
                value = 0.83
            elif s == '\t':
                value = 1.3
            else:
                value = min(2.2, 1.6 + 0.12 * math.log2(len(s)))
        elif previous.endswith('\n'):
            value = 0.2 if ' ' in s else 0.0
        else:
            value = 0.4
    elif s == '__':
        value = 0.7
    elif s == '\\t':
        value = 0.5
    elif s in ('\\x', '\\xa'):
        value = 0.6
    elif s and not s.strip():
