            return -5.5
        if word in {'resort', 'digit', 'digits', 'remaining', 'surviving'}:
            return -2.8
        if word in {'access', 'activity', 'login'}:
            return -2.6
        if word in {'seen', 'written', 'known', 'used'}:
            return -1.0
        if word in {'year', 'years', 'month', 'months', 'time', 'few'}:
            return 1.2 if capital_last else 0.7
        if word in {'date', 'page', 'term', 'post', 'posts'}:
