@lru_cache(maxsize=16384)
def letters(text):
    # Fold accents and transliterate individual letters, without mistaking
    # part of a multi-letter reading for a single letter.
    result = []
    for ch in text:
        reading = anyascii(ch)
        result.append(reading if len(reading) <= 1 else '_')
    return ''.join(result)


def response(s, previous):
    w = s.strip().lower()
    if s and not s[0].isspace():
        consonant = previous[-1:]
        if consonant in ('b', 'p'):
            if w == 'et':
                return 8.3 if consonant == 'b' else 7.6
            if w.startswith('et'):
                if len(w) == 3:
                    return 5.1 if w[-1] in 'aeiou' else 6.2
                return 3.2
            if w.startswith('ell'):
                return 1.2 if len(w) <= 4 else 0.1
            if w.startswith('el'):
                return 0.3
            if w in ('at', 'ata'):
                return 2.2 if consonant == 'b' else 1.4
            if w.startswith(('at', 'it')):
                return 0.4
            if w.startswith(('iet', 'ert')) or w == 'e':
                return 0.7
            if w.startswith('amm'):
                return -5.2
            if w.startswith('am'):
                return -0.7
            if w.startswith('em'):
                return -3.1 if len(w) <= 3 else -0.5
            if w.startswith('im'):
                return -0.4
        if previous.endswith(('be', 'pe')):
            if w.startswith('et') or w in ('t', 'th', 'ti'):
                return 3.1
            if w == 'r':
                return -0.5
