    if w.endswith(('bet', 'pet')) and len(w) <= 4:
        if s.strip().isupper():
            return 7.0
        return 3.5 if s[0].isspace() else 4.7
    if w in ('beth', 'peth'):
        return 6.2 if s.strip()[0].isupper() else 2.6
    if w in ('bets', 'pets', 'bett', 'pett'):
        return 2.0
    if ((w.endswith(('bet', 'pet')) and len(w) <= 6)
            or (w.startswith(('bet', 'pet')) and len(w) <= 5)):
        return 1.0
    if w in ('bem', 'pem'):
        return -2.3
    if w in ('bell', 'bill'):
        return 1.0
    if w in ('bat', 'pat') or w.startswith(('beet', 'beat')):
        return 0.5
    if w == 'beta':
