    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, last = ('', 0.0) if start else carry[1:]
    s = letters(prefix.token_strings[-1])
    raw = response(s, previous)
    value = raw - (0.25 if start else 0.0)
    if s and not s[0].isspace():
        value += 0.1 * max(0.0, last)
    return (doc, (previous + s.lower())[-3:], raw), value

"""A source-code receiver detector, not a general code detector.

The main positive responses are on self/this, especially at the beginning of
an indented code line. Parenthesized method parameters respond less strongly.
Nearby assignments, member accesses and declarations help separate code from
English uses of these words. Receiver-access operators and visibility-qualified
function declarations also respond. Two negative rules cover comment/markup openers at the very start of a document. Other
lexical effects are deliberately left at zero.
"""
import re

READS = ()


def receiver_value(word, spelling, previous):
    line = re.split(r'\n|\\n|\\r', previous)[-1]
    numbered = bool(re.match(r' *\d+\t', line))
    indented = bool(line and re.fullmatch(r'(?: *\d+\t)?[ \t]+', line))
    punctuation = bool(re.search(r'[{};]', previous))
    member = bool(re.search(r'[A-Za-z_]\w*\.[A-Za-z_]', previous))
    receiver = bool(re.search(r'\b(?:self|this)\.', previous))
    declaration = bool(re.search(r'\bdef\b', line))
    keyword = bool(re.search(
        r'\b(def|class|public|private|function|return|const|var|let|import)\b',
        previous))
    returning = bool(re.search(r'\b(return|yield|await)\s*$', previous))
    bare = spelling == word
    parenthesized = spelling.startswith('(')

    # A long plain-English line can follow a quoted source-code example.
    prose = len(re.findall(r'[A-Za-z]+', line)) > 8
    if prose and not re.search(r'[{};=()<>._]', line):
        return 0.0 if word == 'this' else -0.5

    if word == 'this':
        if spelling.startswith('$') or previous.endswith('$'):
            return 6.5
        if parenthesized:
            return 5.2
        if spelling.startswith('\t'):
            return 7.8
        if returning:
            return 7.8 if receiver else 6.8
        if punctuation:
            if indented:
                return 6.6 if numbered else 8.1
            if re.search(r'[A-Za-z]$', previous):
                return 5.0 if receiver else 0.0
            return 6.2 if keyword or bare else 2.4
        if indented:
            return 1.4
        return 0.7 if bare else 0.0

    if previous.endswith('`'):
        return 1.6
    # self as a word fragment (myself, yourself, ...) is not a receiver.
    if bare and re.search(r'[A-Za-z]$', previous):
        return -2.0
    if parenthesized:
        return 2.6 if declaration else 3.9
    if spelling.startswith(('=', '[')):
        return 3.5
    if indented or spelling.startswith('\t'):
        value = 5.2 if punctuation else 6.6
        return value - 1.5 if numbered else value
    if re.search(r'[=+*/-]\s*$', previous):
        return 4.5
    if member:
        if declaration:
            return 2.3 if bare else 4.7
        return 3.2 if punctuation else 4.4
    if keyword:
        return 2.8
    return 1.6 if punctuation else -0.4


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    recent = previous[-180:]
    value = 0.0
    if not previous and token in ('//\n', '<!'):
        value = -6.85 if token == '//\n' else -7.69
    elif token == '->' and re.search(r'\bthis\s*$', recent):
        value = 9.3
    elif token == '::' and re.search(r'\b[Ss]elf$', recent):
        value = 4.7 if '$' in recent or 'function' in recent else 1.3
    elif token.strip() == 'function' and re.search(
            r'\b(public|private|protected)(?: +static)?$', recent):
        value = 1.8
    else:
        match = re.fullmatch(r'[ \t]*[($=\[]?(self|this)', token)
        if match:
            value = receiver_value(match[1], token, recent)
    return (doc, (previous + token)[-250:]), value

