"""Fires on `this` / `self`: the object a method call or field access starts from.

Layer-1 MLP component 4809 (down_proj). It is silent on almost all text. It fires
when `this` or `self` begins a member access in source code:
  - `this.socket`, `self.rect`, `return this.x`, `x = self.y`   -> strong (about 6 to 9)
  - the `->` in PHP's `$this->method()`                          -> strong (about 9)
  - `self` as a method's first parameter, `__init__(self, ...)` -> moderate (about 3.4)
In ordinary English ("use this method", "on this topic") it stays near 0.
The only context used is the token just before `this`/`self`: indentation, `=`,
`return`, an opening bracket or sigil, or a code operator means code is starting.
What it leaves out: the activation varies with the context (sd about 2 within the
strong group), and a few receivers such as the variable `holder` (Android code) or
`cls` also fire, which this rule does not cover.
"""

READS = ()

SELF_WORDS = {"this", "self"}
# Tokens after which an expression (and so a receiver like `this`) begins in code.
CODE_BEFORE = {
    "=", "return", "(", "$", "!", "!!", "{", "[", "&", "*",
    "+", "&&", "||", "<", "?", "',", '",',
}


def word(s):
    """The token without the leading spaces, tabs, brackets or sigils glued to it."""
    return s.lstrip(" \t([$!&*")


def is_indent(s):
    """A whitespace token that starts an indented line of code."""
    return s.strip() == "" and ("\n" in s or "\t" in s or len(s) >= 2)


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    if cur.strip() == "->":
        # PHP/Perl `$this->`: the arrow right after the self reference.
        return None, 9.0 if word(prev) in SELF_WORDS else 0.0
    if word(cur) not in SELF_WORDS:
        return None, 0.0
    if is_indent(prev) or prev.strip() in CODE_BEFORE:
        return None, 6.5
    if cur.startswith("(") or prev.endswith("("):
        return None, 3.4
    if prev.strip() == "if":
        return None, 3.6
    if prev.strip() == "in" and word(cur) == "self":
        return None, 5.0
    return None, 0.0

