"""Membership operators, and Chinese expressions for a whole span or expanse.

This approximation gives negative pulses on iteration/membership syntax and on
Chinese `one/whole` constructions, especially an entire life, body, time,
or expanse. The Vietnamese phrase "một cách" also gets a negative pulse.
Repeated middle dots give a positive pulse; other text defaults to zero. This is a short rule approximation, not a general parser.
"""
import re

READS = ()
LOOP = re.compile(
    r'\b(?:for|foreach)(?=\s|\()\s*\(?\s*'
    r'(?:(?:const|let|var|int|auto|String|each|[A-Z]\w*)\s+)?'
    r'[A-Za-z_]\w*(?:\s*,\s*[A-Za-z_]\w*)*\s*\)?\s*$',
    re.IGNORECASE,
)
TEST = re.compile(r'\b(?:if|elif|assert)\s+[^\s]+(?:\s+not)?\s*$')
# Whole life, body, time, expanse, chestful, ground, face, or atmosphere.
WHOLE = set('生身时時片腔地脸臉派')
# Idioms for a whole course, area, generation, or single-minded action.
COURSE = set('路辈輩朝气氣带帶意往连連')
# Events, groups, and small quantities introduced with "one".
UNITS = set('家场場阵陣口刻世夜声聲脚腳心行番招')


def response(token, tail):
    word = token.strip()
    line = tail.replace('\\n', '\n').replace('\\t', '\t').split('\n')[-1]
    if word and len(word) >= 2 and set(word) == {'·'}:
        return 'dots', 1.08
    if word == '∈':
        return 'math', -0.72
    if word == 'in' and tail.endswith('\\'):
        return 'latex', -0.8
    if word == 'range':
        if tail.rstrip().endswith(':='):
            return 'go', -1.73
        if re.search(r'\bin\s*$', line):
            return 'range', -0.37
    if token == ' of' and re.search(
        r'\bfor\s*\(\s*(?:const|let|var)\s+\w+\s*$', line
    ):
        return 'loop', -1.8
    if token in (' in', ' In'):
        m = LOOP.search(line)
        if m and not re.search(r'\b(?:example|instance|use)\s*$', line):
            before = line[:m.start()]
            code_context = (
                re.fullmatch(r'\s*\+?\s*\d*\s*(?:#|//)?\s*', before)
                or '(' in line[m.start():]
                or before.count('[') > before.count(']')
                or re.search(r'\w+\([^)]*$', before)
                or before.rstrip().endswith(('}', ':', ';'))
            )
            if code_context:
                return 'loop', -1.75
        if TEST.search(line) and re.search(r'[=():\[\]_;]', line):
            return 'test', -0.9
    if word == ':' and re.search(
        r'\bfor\s*\([^;:]+\s+\w+\s*$', line
    ):
        return 'loop', -1.7
    if word == 'cách' and tail.lower().rstrip().endswith('một'):
        return 'manner', -3.5
    # Look across token boundaries, but assign the pulse to the noun,
    # not to an isolated numeral token.
    joined = tail[-2:] + word
    if '一切' in word:
        return 'all', -6.2 if word == '一切' else -4.5
    if len(word) <= 5:
        for i, ch in enumerate(word):
            before = joined[:len(joined) - len(word) + i]
            if (before.endswith(('满', '滿'))
                    and before[-2:-1] not in ('丰', '豐')
                    and ch in '头頭身脸臉场場地'):
                return 'full', -3.5
            if before.endswith('一') and before[-2:-1] not in ('第', '同'):
                if ch in WHOLE:
                    return 'whole', -4.6 if i else -6.2
                if ch in COURSE:
                    return 'course', -2.5 if i else -3.0
                if ch in UNITS:
                    return 'unit', -0.9 if i else -2.0
        if word == '切' and tail.endswith('一'):
            return 'all', -6.2
        if ('一系列' in word
                or (word.startswith('系列') and tail.endswith('一'))):
            return 'series', -1.5
        if word.startswith('一直'):
            return 'continuous', -0.42
    return 'other', 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    _, value = response(token, tail)
    return (doc, (tail + token)[-180:]), value

