"""Word-table program for layers.1.mlp.down_proj:4812.

The component fires on words that look back at earlier work or check a result
("again", "above", "still", "same as before", "Here's the result", "Now let me verify",
"as expected"), and it is stronger inside chat turns. Each word has a fixed value taken
from its average activation in the training data. Words that follow a check verb
("verify the", "review the") get a moderate value. The first token of each document
gets a small negative value. Everything else is 0.
"""
READS = ()
LOOK_BACK = {"again": 0.48, "above": 0.40, "still": 0.33, "previously": 0.35, "earlier": 0.36,
             "previous": 0.24, "same": 0.16, "similar": 0.23, "aforementioned": 0.36,
             "shown": 0.24, "expected": 0.27, "equivalent": 0.25, "seems": 0.30}
CHECKING = {"verify": 0.31, "review": 0.34, "check": 0.11, "results": 0.12, "result": 0.19,
            "file": 0.18, "correctly": 0.40, "indeed": 0.44, "clearly": 0.34, "obviously": 0.38,
            "successfully": 0.25, "properly": 0.20}
OPENERS = {"here": 0.33, "now": 0.22, "this": 0.08, "let": 0.14}
NEGATIVE = {"alternatively": -0.17, "considering": -0.34, "meaning": -0.20, "something": -0.14,
            "anything": -0.15, "✓": -0.23}
CHECK_VERBS = {"verify", "check", "review", "confirm", "test"}
DOC_START = -0.09

def step(carry, prefix, upstream):
    # carry: 1 while inside a chat turn written by the assistant or user, else 0
    role = carry or 0
    word = prefix.token_strings[-1].strip().lower()
    prev = prefix.token_strings[-2].strip().lower() if len(prefix) > 1 else ""
    if prev == "<|im_start|>" and word in ("assistant", "user"):
        role = 1
    if word in ("<|endoftext|>",):
        role = 0
    if len(prefix) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        return role, DOC_START
    scale = 1.5 if role else 1.0
    if prev in CHECK_VERBS and word in ("the", "this", "that", "it", "its"):
        return role, 0.4 * scale
    for table in (LOOK_BACK, CHECKING, OPENERS, NEGATIVE):
        if word in table:
            return role, float(table[word]) * scale
    return role, 0.0

