"""A sparse, mainly cross-reference-syntax response.

LaTeX label names and their braces are strongest; ref/cite commands are
weaker. Other explicit responses cover web-address starts in East Asian
text, title headers, dotted leaders, and the return/origin ideographs.
This deliberately leaves ordinary prose near zero rather than memorizing
its many small, token-specific responses.
"""
import re
import regex

READS = ()
EAST_ASIAN = regex.compile(r'[\p{Han}\p{Hiragana}\p{Katakana}\p{Hangul}]')
KANA = regex.compile(r'[\p{Hiragana}\p{Katakana}]')
REFERENCE = re.compile(r'\\(?:eq|page|auto|c)?ref$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        tail, previous = '', ''
    else:
        _, tail, previous = carry
    token = prefix.token_strings[-1]
    text = tail + token
    value = 0.0

    # Cross-reference commands: label definition, reference, citation.
    if re.search(r'\\label$', text):
        if re.search(r'\\begin\{[^}]+\}\s*\\$', tail):
            value = 12.0 if '{aligned}' in tail else 15.0
        elif tail.endswith('$$\\'):
            value = 13.5
        elif re.search(r'\\end\{(?:array|tabular)\}[^\\]*\\$', tail):
            value = 7.0
        elif previous.endswith('}\\'):
            value = 12.5
        elif previous.startswith(' '):
            value = 9.2
        else:
            value = 12.0
    elif REFERENCE.search(text):
        value = 3.6
    elif re.search(r'\\cite[a-z]*$', text):
        value = 0.65
    elif token.startswith('{'):
        if re.search(r'\\label$', tail):
            value = 5.7 if token == '{' else 1.2
        elif REFERENCE.search(tail):
            value = 3.6 if token == '{' else 0.7

    if text.endswith('data-label'):
        value = 3.1

    # Addresses are more active in Chinese/Japanese surrounding text.
    address = token.strip(' -')
    if address in ('http', 'https', 'www') or token == '://':
        asian = bool(EAST_ASIAN.search(tail))
        if token == '://':
            value = 1.5 if asian else -0.2
        elif address == 'www':
            value = (1.4 if token.startswith(' ') else 2.2) if asian else -0.1
        else:
            value = 1.6 if asian else -0.1

    if token == ':' and (tail == 'Title' or tail.endswith('<|endoftext|>Title')):
        value = 7.54
    if token and set(token) == {'·'} and len(token) > 1:
        value = 2.42 if not previous or set(previous) == {'·'} else 0.0

    # Literal return/origin characters have opposite lexical responses.
    if token == '返':
        value = 5.5 if KANA.search(tail) else 7.5
    elif token == '返回':
        value = 1.6
    elif token == '原':
        value = -1.0 if KANA.search(tail) else -2.3
    return (doc, text[-64:], token), float(value)

programs.haiku:
"""Indefinite determiners (a, an, another, one, more) and 'for' take a signed activation set by
the word before them: after a verb of giving or providing (provide, gives, offers, allow ...)
strongly positive; after make/create/with/has weakly positive; after a relational word
(without, about, such, be, of, to ...) negative. Chinese causatives 令人 / 让人 ('makes
people ...') are strongly positive. Everything else is 0."""

READS = ()

DETERMINERS = {" a", " an", " another", " one", " more"}
GIVE = {"provide", "provides", "provided", "providing", "give", "gives", "gave", "giving",
        "offer", "offers", "offered", "offering", "allow", "allows", "allowed", "allowing",
        "produce", "produces", "produced", "producing", "after"}
MAKE = {"make", "makes", "made", "making", "create", "creates", "created", "creating",
        "add", "adds", "added", "adding", "take", "takes", "took", "taking", "receive",
        "received", "with", "has", "have", "had", "at", "during"}
NEG_STRONG = {"without", "about", "be", "'s", "there", "need", "needs", "see", "find", "such",
              "exists", "require", "requires", "consider", "against", "upon"}
NEG_WEAK = {"of", "to", "on", "by", "into", "from", "include", "includes"}
CAUSE_CN = {"令人", "让人", "使人", "让我", "叫人", "令我", "给人", "让他", "让她", "让你"}


def step(carry, prefix, upstream):
    t = prefix.position
    cur = prefix.token_strings[t]
    if cur in CAUSE_CN:
        return None, 3.4
    if t == 0:
        return None, 0.0
    prev = prefix.token_strings[t - 1].strip().lower()
    if cur == " for":
        return None, (2.2 if prev in GIVE | MAKE else 0.0)
    if cur not in DETERMINERS:
        return None, 0.0
    if prev in GIVE:
        return None, 1.7
    if prev in MAKE:
        return None, 0.3
    if prev in NEG_STRONG:
        return None, -0.7
    if prev in NEG_WEAK:
        return None, -0.3
    return None, 0.0

programs.sol:
"""Approximate the large symbol/word responses with rounded training means.

Negative triggers: degree notation, numerical micro-units, middle-dot separators
following Han text, and Chinese state words. Positive triggers: responsibility
words and paired middle dots outside Han text. A positive document-initial bias
and a special response to the colon in initial 'Title:' cover boundary effects.
Most smaller, token-specific background responses are deliberately left at zero.
"""
import regex

READS = ()
HAN = regex.compile(r'\p{Script=Han}')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, previous, tail = 0, '', ''
    else:
        _, position, previous, tail = carry
    token = prefix.token_strings[-1]
    word = token.strip()
    before = tail.rstrip()
    number_before = bool(before and before[-1].isdigit())
    value = 0.0

    if word == '°':
        value = -0.32
        if number_before:
            value = -0.55 if token.startswith(' ') else -0.94
    elif word == 'circ' and before.endswith('\\'):
        value = -1.25 if regex.search(r'\d+\^\\$', before) else -0.74
    elif word in ('μ', 'µ') and number_before:
        value = -0.50
    elif word == 'º':
        value = -0.12
    elif word == '℃':
        value = -0.16
    elif word == '··':
        value = -0.53 if HAN.search(before[-2:]) else 0.37
    elif word == '·':
        value = -0.65 if HAN.search(before[-2:]) else -0.12
    elif word in ('责', '責'):
        value = 1.8
    elif word in ('负责', '負責'):
        value = 1.1
    elif word in ('负责人', '負責人', '职责', '職責'):
        value = 0.8
    elif word in ('状态', '狀態'):
        value = -0.6

    # At a document boundary, content tokens have a positive baseline.
    if position == 0 and value == 0.0:
        if word.isdigit():
            value = 0.30
        elif word.startswith('-') and word[1:].isalpha():
            value = 0.83
        elif word.isalpha() and (word.isascii() or word.islower()):
            value = 0.18
        else:
            value = 0.05

    if position == 1 and previous == 'Title' and token == ':':
        value = 3.98
    return (doc, position + 1, token, (tail + token)[-40:]), value

programs.haiku:
"""Layer-1 MLP down-projection, component 4816: a German "st" / "const" / "un-" piece detector.

What it responds to, in plain terms:
- The "st" sound closing a word that the tokenizer split into pieces, mainly in German
  text: Kun|st (Kunst), Dien|st (Dienst), ein|st (einst), Ern|st, sonst, inst, nst, ünst.
  It is strong when the surrounding text is German and weaker elsewhere. It stays silent
  after a digit (1st, 21st), the ordinal suffix.
- "const" right after a C-family access word (public, private, extern, static), as in
  "public const int". Plain "const" elsewhere is weak; "export const" in TypeScript is too.
- "usr" as in /usr/bin.
- Short pieces that split off an "un" prefix (un|con, un|R, UN|R), and word starts
  such as " uns", " unre", " unst", which open a word beginning with "un-".

The component is sparse: it is near zero on almost every token, and these rules cover
its largest activations. The activation values below are rough group means from
training text, so the program is a readable approximation, not an exact fit.

Each step reads the current token, the token before it, and the last 32 tokens of the
same document (only to judge whether the text is German). It keeps no state between steps.
"""

READS = ()

# Common German function words: a cheap test for "this text is German".
GERMAN = {
    "der", "die", "das", "und", "ist", "nicht", "mit", "den", "ein", "eine", "zu",
    "für", "auf", "auch", "sich", "dem", "von", "nach", "wie", "aber", "oder", "wir",
    "sie", "es", "ich", "du", "dass", "im", "des", "werden",
}
# Word pieces that are the "st" cluster (lowercase "st", "inst", "nst", ...), and whole
# German words that end in it.
ST_PIECES = {"st", "nst", "inst", "ünst", "ст", "sst", "bst", "sth"}
GERMAN_WORDS = {"kunst", "ernst", "sonst"}
CONST_MODIFIERS = {"public", "private", "protected", "extern", "static"}
UN_PIECES = {" uns", " unre", " unst", " unsub", " unb", " unr", " uncon", " uncomp"}
UN_PREFIXES = {"un", "Un", "UN", "ün"}

# Activation levels (roughly the group means measured on training text).
VALUE = {
    "st_german": 2.5,   # "st" piece in German text
    "st_other": 1.0,    # "st" piece in other text
    "const_after_modifier": 5.0,
    "const_other": 0.3,
    "usr": 1.1,
    "un_piece": 0.7,
    "un_short_2": 1.2,  # 1-2 letters after an un prefix
    "un_short_3": 0.6,  # 3 letters after an un prefix
}
GERMAN_THRESHOLD = 0.05  # share of German function words in the last 32 tokens


def german_share(prefix, window=32):
    """Share of the last `window` tokens, in the same document, that are German function words."""
    t = len(prefix) - 1
    doc = prefix.document_ids[t]
    words = [
        prefix.token_strings[i].strip()
        for i in range(max(0, t + 1 - window), t + 1)
        if prefix.document_ids[i] == doc
    ]
    return sum(w in GERMAN for w in words) / max(len(words), 1)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    prev = prefix.token_strings[-2] if len(prefix) > 1 else ""
    value = 0.0
    if token in ST_PIECES or token.strip().lower() in GERMAN_WORDS:
        if not prev.strip()[-1:].isdigit():
            german = german_share(prefix) >= GERMAN_THRESHOLD
            value = VALUE["st_german"] if german else VALUE["st_other"]
    elif token.strip() == "const":
        value = VALUE["const_after_modifier"] if prev.strip() in CONST_MODIFIERS else VALUE["const_other"]
    elif token == "usr":
        value = VALUE["usr"]
    elif token in UN_PIECES:
        value = VALUE["un_piece"]
    elif prev in UN_PREFIXES and token.isalpha() and len(token) <= 3:
        value = VALUE["un_short_2"] if len(token) <= 2 else VALUE["un_short_3"]
    return carry, float(value)

programs.sol:
"""Positive pulses for European 'have' auxiliaries and their contractions.

A small recent-word language test separates e.g. French 'a' from English
'a', and German 'hat' from an English hat. English have/has/had are weaker,
with 'have' after a modal or 'to' distinguished from finite 'have'. Words
split across tokens are assembled. Romanian clitic-plus-'a' gives a pulse
too. Infinitives, participles and conditional forms are generally weaker.
Everything else is zero; history resets between documents.
"""
import re


def lexicon(text):
    return frozenset(text.split())


READS = ()
LANGUAGES = {
    'en': lexicon(
        'the a an to of in is are was were be been for and or but if '
        'then that this these those it with from not which who will '
        'would can could should have has had'),
    'pt': lexicon(
        'eu você ele ela nós eles elas os das dos não é uma para que '
        'com em seu sua um ao do na no'),
    'fr': lexicon(
        'je tu il elle nous vous ils elles une des du les est sont dans '
        'pour avec pas qui que au aux ce cette mais sur ses son leur '
        'ces ne fait plus été'),
    'es': lexicon(
        'yo tú usted nosotros ustedes ellos ellas una los las del para '
        'por como pero que en con su sus también al se no es el un más '
        'esta este'),
    'it': lexicon(
        'io tu lui lei noi voi loro una gli il della delle degli alla '
        'nel nella per che con non sono è si questo questa anche mi lo '
        'le'),
    'de': lexicon(
        'ich du er sie wir ihr es der die das den dem des ein eine '
        'einer einen und zu im mit nicht auch sich auf von für ist als '
        'aber'),
    'north': lexicon(
        'jag du han hon vi ni det och att inte som på av för den er '
        'ikke med til en jeg de het een van zijn ik hij wij je te maar'),
}
FRENCH_HAVE = lexicon(
    'avons avez ont avait avaient avais aviez avions aurai aura '
    'auront auraient aurait avoir eu')
ITALIAN_HAVE = lexicon(
    'ho hai ha hanno abbiamo avete avere avuto avevo aveva avevano '
    'avrei avrebbe')
SPANISH_HAVE = lexicon(
    'he has ha hemos habéis han haya hayan haber había habían '
    'habíamos hubo hubiera hubieran habrían habría')
GERMAN_HAVE = lexicon(
    'habe haben hat hast habt hatte hatten hattet hätte hätten '
    'hättest gehabt')
NORTHERN_HAVE = lexicon('har haft havde hadde hatt heb hebt heeft hebben hadden gehad')
CANDIDATES = (FRENCH_HAVE | ITALIAN_HAVE | SPANISH_HAVE | GERMAN_HAVE |
              NORTHERN_HAVE | {'a','as','ai','ve','have','has','had','having','ave','ava'})
MODALS = lexicon('to will would shall should can could may might must ought')
PRONOUNS = lexicon('i we you they')


def category(carry, doc, token):
    # The trailing word may have begun in an earlier token.
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    text = (tail + token).lower().replace('’', "'")
    state = (doc, text[-256:])
    if not token or not token[-1].isalpha():
        return state, 'quiet'
    match = re.search(r'([^\W\d_]+)$', text)
    if not match:
        return state, 'quiet'
    word = match.group(1)
    if word not in CANDIDATES:
        return state, 'quiet'
    before = text[:match.start()]
    words = re.findall(r'[^\W\d_]+', before)[-32:]
    prev = words[-1] if words else ''
    if word == 've' and before.endswith("'"):
        return state, 'contracted_have'
    if word == 'have':
        if prev in MODALS or before.endswith("n't "):
            return state, 'english_infinitive'
        if prev in PRONOUNS:
            return state, 'english_pronoun_have'
        return state, 'english_other_have'
    if word == 'has':
        return state, ('english_personal_has' if prev in ('he','she','there')
                       else 'english_has')
    if word == 'had':
        return state, ('english_personal_had' if prev in PRONOUNS | {'he','she'}
                       else 'english_had')
    if word == 'having':
        return state, 'english_having'
    if word == 'ai' and prev in ('j', 'n', 'm') and before.endswith("'"):
        return state, 'french_ai'
    if word == 'a' and before.endswith("'") and prev in ('n','l','m','t'):
        return state, 'french_contracted'
    if word == 'a' and before.endswith('-') and prev in ('s','l','v'):
        return state, 'romanian_clitic'
    if word in ('a','as') and token[-1].isupper():
        return state, 'quiet'
    # Most matching recent function words wins; two distinct cues are needed.
    scores = {lang: sum(w in lex for w in set(words))
              for lang, lex in LANGUAGES.items()}
    def speaks(lang):
        return scores[lang] >= 2 and scores[lang] == max(scores.values())
    if (speaks('fr') or word in {'avons','avez','avait','avaient','aviez','avions'}
            or (word == 'a' and prev in ('il','elle'))
            or (word == 'ont' and scores['fr'] >= 1 and scores['en'] <= 2)):
        if word in ('ave','ava'):
            return state, 'have_stem'
        if word in ('avoir','eu','aura','aurai','auront','auraient','aurait'):
            return state, 'french_nonpresent'
        if word == 'ont':
            return state, 'french_plural'
        if word in FRENCH_HAVE or word == 'a' or (word == 'as' and prev == 'tu'):
            return state, 'french_have'
    if (speaks('it') or word in {'hanno','abbiamo','avete','avevo','aveva','avevano'}
            or (word == 'ho' and prev in ('io','non','mi','lo','ti'))):
        if word in ('ave','ava'):
            return state, 'have_stem'
        if word in ITALIAN_HAVE:
            if word == 'avere':
                return state, 'italian_infinitive'
            if word not in ('ho','hai','ha','hanno','abbiamo','avete'):
                return state, 'italian_past'
            return state, 'italian_have'
    if word in SPANISH_HAVE and (speaks('es') or
            (word == 'ha' and prev in ('se','no','que'))):
        present = ('he','ha','has','hemos','habéis','han','haya','hayan')
        return state, ('spanish_have' if word in present
                       else 'spanish_nonpresent')
    if word in GERMAN_HAVE and speaks('de'):
        return state, ('german_have' if word in ('habe','haben','hat','hast','habt')
                       else 'german_past')
    if word in NORTHERN_HAVE and speaks('north'):
        return state, ('northern_have' if word in ('har','heb','hebt')
                       else 'northern_other')
    return state, 'quiet'

VALUES = {
    'contracted_have': .574, 'english_infinitive': -.084,
    'english_pronoun_have': .31, 'english_other_have': .103,
    'english_personal_has': .32, 'english_has': .06,
    'english_personal_had': .30, 'english_had': .11,
    'english_having': -.024,
    'french_ai': .95, 'french_contracted': .58,
    'french_have': .75, 'french_plural': 1., 'french_nonpresent': .30,
    'italian_have': .88, 'italian_infinitive': .24, 'italian_past': .56,
    'spanish_have': .79, 'spanish_nonpresent': .20,
    'german_have': .56, 'german_past': .33,
    'northern_have': .64, 'northern_other': .41,
    'have_stem': .35, 'romanian_clitic': .9, 'quiet': 0.,
}


def step(carry, prefix, upstream):
    state, kind = category(carry, prefix.document_ids[-1],
                           prefix.token_strings[-1])
    return state, VALUES[kind]

programs.haiku:
"""Perfect-tense auxiliary 'have' (English and other languages), plus the first token of a text."""
READS = ()

PERSON_SUBJECTS = {"I", "we", "you", "they", "he", "she", "who", "that", "We", "You", "They", "He", "She",
                   "io", "noi", "tu", "lui", "lei", "loro", "voi", "je", "nous", "vous", "il", "elle",
                   "ils", "elles", "Il", "Elle", "ich", "wir", "er", "sie", "du", "yo", "él", "ella",
                   "nosotros", "ellos", "eu", "ele", "ela", "não", "non", "ne", "pas"}
CONTRACTED = {"'ve", "’ve"}
HAVE_EN = {"have", "has", "had"}
HAVE_OTHER = {"ha", "hat", "hatte", "hatten", "haben", "habe", "hast", "hab", "han", "hanno",
              "ho", "har", "avoir", "avait", "avons", "avez", "ont", "había", "hätte"}
MODALS = {"would", "will", "can", "should", "may", "might", "could", "must", "to"}

def step(carry, prefix, upstream):
    if prefix.position == 0:
        return None, 0.19
    tok = prefix.token_strings[-1]
    before = prefix.token_strings[-2].strip()
    word = tok.strip()
    if tok in CONTRACTED:
        return None, 0.7 if before in PERSON_SUBJECTS else 0.3
    if word in HAVE_EN or word in HAVE_OTHER:
        if before in PERSON_SUBJECTS:
            return None, 0.35
        if before in MODALS:
            return None, -0.05
        return None, 0.07
    return None, 0.0

"""Rule-based guess for layers.1.mlp.down_proj:4818.

The component fires on an "-in" / "-on" ending that is split off as its own token and
glued onto the letters before it: "act|in", "stat|ins", "Stett|in", "Konstant|in",
"Lat|in", "Valent|ine". How strongly depends on the letter before the ending:

- after t or d it is strong (act|in, Stett|in, Konstant|in);
- after n, l, s or b it is weak;
- after h, v, w, x or y it goes negative (Sh|in, W|in);
- after other letters it is close to zero.

A word piece that already ends in "-tin", "-din" or "-ton" (atin, ulin, antine) is
strong too, and a whole word of six or more letters ending in "-tin" or "-tine"
(Latin, Martin, Valentine) is weakly positive. Cyrillic "ин" / "он" pieces and the
middle-dot run "··" go negative. Everything else is 0. The numbers are scaled to the
component's size, about 1.5 times its unit-strength response, which fits best.
"""

READS = ()

ENDINGS = ("in", "on", "ins", "ine", "ino", "ons", "ina", "ini")
STRONG_ENDINGS = ("tin", "tine", "ton", "din", "dine")
STEM_VALUE = {
    "t": 2.1, "d": 1.8,
    "n": 0.4, "l": 0.4, "s": 0.3, "b": 0.3,
    "h": -0.45, "v": -0.45, "x": -0.45, "y": -0.45, "w": -0.75,
}
OTHER_STEM = 0.08


def step(carry, prefix, upstream):
    t = prefix.position
    cur = prefix.token_strings[t]
    if t == 0 or prefix.document_ids[t] != prefix.document_ids[t - 1]:
        return None, 0.0
    prev = prefix.token_strings[t - 1]
    if cur == "··":
        return None, -0.7
    if cur.startswith(" ") and cur[1:].isalpha():
        if len(cur) >= 6 and cur[1:].lower().endswith(("tin", "tine")):
            return None, 1.0
        return None, 0.0
    if not cur.isalpha() or not prev[-1:].isalpha():
        return None, 0.0
    word = cur.lower()
    if word in ("ин", "он"):
        return None, -0.7
    if word.endswith(STRONG_ENDINGS):
        return None, 1.8
    if word in ENDINGS:
        return None, STEM_VALUE.get(prev[-1:].lower(), OTHER_STEM)
    return None, 0.0

programs.sol:
"""Approximate an early spelling feature: FR, especially fraction and Franc/Frank.

Keep the unfinished word, not the whole text. Responses are larger when short
FR stems finish across token boundaries, smaller for longer derivatives and
most FL spellings. Romanize other alphabets but keep Latin accents distinct.
Also reproduce two observed formatting responses: double middle dots, and a
colon after document-initial 'Title'. This is not a general meaning detector.
"""
import re
import unicodedata
from functools import lru_cache
from anyascii import anyascii

READS = ()


@lru_cache(maxsize=8192)
def romanize(text):
    return ''.join(
        ch.lower() if ch.isascii() or 'LATIN' in unicodedata.name(ch, '')
        else 'a' if ch == 'ا' else anyascii(ch).lower()
        for ch in text
    )


def spelling_value(word, token, previous):
    match = re.search(r'((?:f|ph)[rl])([^f]*)\Z', word)
    if not match:
        return 0.0
    cluster, tail = match.groups()
    whole = cluster in token
    after_f = not whole and previous.endswith(('f', 'ph'))
    cluster = cluster.replace('ph', 'f')
    after_cluster = not whole and previous.endswith(cluster)
    split = not whole

    if cluster == 'fr':
        if re.fullmatch(r'actions?', tail):
            if word.endswith(('refraction', 'refractions', 'diffraction')):
                return 2.8
            return 5.3 if whole else 6.6
        if re.fullmatch(r'an(?:c|k|ch|ck|z|tz|ts|cs|ks)?', tail):
            if whole:
                return 4.0 if tail == 'an' else 3.5 if tail == 'anz' else 5.9
            if tail == 'an':
                return 6.0
            if tail.endswith('s'):
                return 4.6
            return 10.5 if previous == 'r' or previous.endswith('fran') else 8.0
        if tail.startswith('an'):
            if previous in ('fran', 'franc', 'frank') and len(token) <= 2:
                return 4.0
            return 3.5 if after_cluster else 3.0 if after_f else 0.85
        if tail in ('a', 'ac', 'ak', 'ag', 'act'):
            if previous.endswith(('\\', '\\d', '\\c', '\\t')):
                return 0.2
            if tail == 'a':
                return 4.0 if after_f else 1.3
            return 5.8 if split else 2.0
        if tail.startswith('act'):
            return 4.8 if previous == 'r' else 2.0 if after_cluster else 1.0
        if tail == 'ench':
            return 1.55 if whole else 0.0
        if tail in ('é', 'équ', 'än', 'änk'):
            return 3.8 if split else 1.0
        if tail.startswith(('ü', 'eu', 'em')):
            return 1.0 if after_f else -0.6
        if not tail:
            return 1.6 if after_f else 0.95
        if tail in ('e', 'en', 'enc', 'es', 'esc', 'esco', 'eg'):
            return 0.35 if whole else 3.0 if after_cluster else 1.8
        return 0.5 if after_f else 0.05

    if tail.startswith('ank'):
        return 4.0 if whole or after_cluster else 2.0
    if tail in ('uor', 'uores', 'ores'):
        if not split:
            return 0.3
        return 1.5 if tail == 'ores' else 7.0 if previous == 'lu' else 4.0
    if tail in ('é', 'éch', 'è'):
        return 3.8 if split else 0.8
    if tail.startswith(('ü', 'ø')):
        return -1.7
    if split and re.fullmatch(r'[aeio][bcdfghjklmnpqrstvwxyz]{1,3}', tail):
