    return 0.4 if after_f else 0.05


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', '', 0)
    _, word, previous, position = carry
    raw = prefix.token_strings[-1]
    token = romanize(raw)
    title_colon = position == 1 and word == 'title' and raw == ':'
    match = re.search(r'[^\W\d_]+\Z', word + token)
    word = match.group()[-64:] if match else ''
    value = spelling_value(word, token, previous)
    if token in ('frank', 'franc'):
        value += 3.0 if position == 0 else 1.4
    if raw == '··':
        value = -1.42
    elif title_colon:
        value = -5.82
    elif token == '.r' and previous.strip() == 'f':
        value = 3.45
    return (doc, word, token, position + 1), value

programs.haiku:
"""Layer-1 MLP down_proj component 4819: a "Fra-" word detector.

The program reads the word being spelled: the letters since the last non-letter (reset at
each new document), lower-cased. The component fires on the token that completes or extends
a word of the "fr"/"fra" family:

- strongly on "fraction(s)", "Franc", "Frank", and the capital "FRACT" of FRACTRAN, including
  "Frank" or "Franc" split across tokens ("Fr" + "ank", "F" + "RACT");
- moderately on "Frances", "fra", "frag", and on "fran"/"fract" inside a longer word
  (enfranchise, refraction, infraction);
- weakly on "France", "French", "fr", and other fran-/fren-/fract- words.

Ordinary "fr" words (from, free, front, friend, fruit) stay near zero, and "fra" inside other
words is small. It is negative on the middle-dot leader token "··" (dot runs in tables of
contents), and on the ":" of a "Title:" that opens a document.

The values are the component's average activation on training text, rounded.
"""

import re

READS = ()

STRONG = {"fraction": 5.5, "fractions": 5.8, "fract": 4.0, "franc": 6.5, "frank": 6.0}
MEDIUM = {"frances": 2.5, "fra": 2.0, "frag": 2.5}
WEAK = {"fr": 1.0, "france": 1.0, "french": 1.0}
WEAK_PREFIXES = ("fract", "fran", "fren")  # other words starting this way
INSIDE = (("fran", 3.0), ("fract", 2.5), ("fra", 0.6))  # text inside a longer word
DOT_LEADER = -1.4
TITLE_COLON = -5.8


def value_of(word):
    for table in (STRONG, MEDIUM, WEAK):
        if word in table:
            return table[word]
    if word.startswith(WEAK_PREFIXES):
        return 1.0
    for text, value in INSIDE:
        if text in word:
            return value
    return 0.0


def is_title_colon(tokens):
    """The ':' of a 'Title:' that opens a document, right after <|endoftext|>."""
    return (
        len(tokens) >= 3
        and tokens[-1] == ":"
        and tokens[-2] == "Title"
        and tokens[-3] == "<|endoftext|>"
    )


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    new_doc = len(prefix) == 1 or prefix.document_ids[-2] != prefix.document_ids[-1]
    word = "" if carry is None or new_doc else carry
    if tok.isalpha():
        word += tok.lower()
    else:
        # the letters after the token's last non-letter, e.g. " fraction" -> "fraction"
        word = re.search(r"[^\W\d_]*$", tok).group(0).lower()
    if tok == "··":
        return word, DOT_LEADER
    if is_title_colon(prefix.token_strings):
        return word, TITLE_COLON
    return word, value_of(word)

