import wordnet
import cedict
import regex

READS = ()
NEGATION = {"not", "cannot", "without", "never", "'t", "’t"}


def opening_value(token):
    """Coarse responses to familiar ways a document begins."""
    word = token.strip()
    if word.lower() == "the":
        return -0.47
    if word in {"import", "package"}:
        return -0.71
    if token == "0":
        return 0.62
    if token == "Title":
        return -0.70
    if token == "#":
        return -0.53
    if token == "<?":
        return 0.43
    if token == "<!":
        return -3.40
    if token == "\t":
        return 0.97
    if token.isspace() and "\n" not in token and len(token) > 1:
        return 0.45
    if word.isascii() and word.isalpha() and not word.isupper():
        return 0.12
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        previous, before_previous, position = '', '', 0
    else:
        _, previous, before_previous, position = carry
    word = previous.strip().lower()
    earlier_word = before_previous.strip().lower()
    value = 0.0
    if token == 'assistant' and previous == '<|im_start|>':
        value = 0.65
    elif token == '<|im_start|>':
        value = 0.08
    elif token == '<tool_call>':
        value = -0.13
    elif token == '</think>':
        value = -0.10
    elif token == ' exactly' and word in NEGATION:
        value = -1.0
    elif token == ' even':
        if word in {"'t", '’t'}:
            value = -5.0 if earlier_word in {'can', 'couldn'} else -4.1
        elif word in NEGATION:
            value = -2.6 if earlier_word in {'may', 'might', 'is'} else -3.2
        elif earlier_word in NEGATION:
            value = -1.3
        elif word in {'barely', 'hardly'}:
            value = -1.1
        elif word in {'can', 'to'}:
            value = -0.65
        else:
            value = -0.08
    elif token == '叫':
        value = -2.2 if previous in {'为什么', '又'} else -4.1
    elif token == '什么叫':
        value = -2.5
    elif token == '叫做':
        value = -1.37
    elif token == '活':
        value = -1.33
    elif token == '招':
        value = -1.65
    elif token in {'有多', '不要太'}:
        value = -1.3
    elif token == ' means':
        if word == 'all':
            value = 3.1
        elif word == 'no':
            value = 1.85
        elif word == 'other':
            value = 1.67
        elif word in {'a', 'of'}:
            value = 1.0
        elif word == 'the':
            value = 0.54
        elif word in {"'s", '’s', 'any', 'our', 'their', 'your'}:
            value = 0.9
        elif 'adjective' in wordnet.parts_of_speech(word):
            value = 0.9
        else:
            value = -0.1
    elif token in {' cause', ' causes'}:
        if (word in {'a', 'the', 'of'}
                or 'adjective' in wordnet.parts_of_speech(word)):
            value = 0.75
    elif (token in {' level', '-level'}
          and word in {'next', 'high', 'highest'}):
        value = -0.8
    elif token == 'php' and previous == '<?':
        value = -1.63 if position == 1 else -0.5
    elif token == ':' and previous == 'Title':
        if position == 1 or before_previous == '<|endoftext|>':
            value = -4.81
    elif len(token) > 1 and regex.fullmatch(r'\p{Script=Han}+', token):
        glosses = set(cedict.glosses(token))
        if 'meaning' in glosses:
            value = 0.6
        elif ('cause' in glosses
              or ('factor' in glosses and 'coefficient' not in glosses)
              or {'reason', 'grounds'} <= glosses):
            value = 0.45
    if position == 0:
        value = opening_value(token)
    return (document, token, previous, position + 1), value

"""A local phrase-pattern approximation, not a general semantic classifier.

Positive: subject + just/also/all, explanatory and conditional clause frames,
and salience relations such as 'importance of'. Negative: indefinite generic
and evaluative descriptions such as 'a kind' or 'an important'. WordNet supplies
adjective tests and noun inflections. Eight recent tokens suffice; documents
reset the history. A separate correction covers document starts and 'Title:'.
"""
from functools import lru_cache
import wordnet

READS = ()
SUBJECTS = set('i we you he she it they'.split())
COPULAS = set('is are was were be'.split()) | {"'s", '’s', "'re", '’re'}
MODALS = set('can could may might must will would should'.split())
AUXILIARIES = COPULAS | MODALS | {
    'has', 'have', 'had', "'ll", '’ll', "'ve", '’ve',
}
FRAMES = {'problem', 'issue', 'trouble'}
EVALUATIONS = set(
    'important significant necessary major certain essential vital critical '
    'possible specific'.split()
)
MANNER = {'way', 'method', 'approach', 'means'}
KINDS = {'type', 'kind', 'form', 'sort'}
PARTS = {'part', 'piece', 'component'}
GENERIC = MANNER | KINDS | PARTS | set(
    'place state matter variety bit work result time model process step source '
    'course procedure mechanism topic experience look'.split()
)
RELATIONS = set(
    'nature power role impact effect value beauty meaning dimensions '
    'possibility matter'.split()
)
INDEFINITE = {'a', 'an', 'another', 'two', 'three', 'several'}


@lru_cache(maxsize=20000)
def adjective(word):
    return 'adjective' in wordnet.parts_of_speech(word)


@lru_cache(maxsize=20000)
def generic_noun(word):
    for base in wordnet.base_forms(word, 'noun'):
        if base in GENERIC:
            return base
    return word


def clean(token):
    return token.strip().strip('"“”').lower()


def predict(token, history):
    w = clean(token)
    previous = [clean(s) for s in history]
    p = previous[-1] if previous else ''
    q = previous[-2] if len(previous) > 1 else ''
    if not history:
        if w.isascii() and w.isalpha() and len(w) <= 2:
            return -0.38
        return -0.24 if any(c.isalpha() for c in w) else -0.14
    if token == ':' and history == ('Title',):
        return 3.36
    # Do not confuse an identifier's internal fragment with an English word.
    if token and token[0].isalpha() and history[-1][-1:].isalpha():
        return 0.0

    if w == 'just':
        if p in SUBJECTS:
            return 1.57
        if p in COPULAS | MODALS:
            return 1.98 if q == 'it' else 0.75
        return 0.33
    if w == 'also':
        if p in COPULAS and q == 'there':
            return 1.42
        if p in SUBJECTS or (p in AUXILIARIES and q in SUBJECTS):
            return 0.82
        return 0.16 if p in AUXILIARIES else 0.06
    if w == 'all':
        if p == 'we' or (p in COPULAS and q == 'we'):
            return 1.65
        if p in SUBJECTS | {'them'} or (p in COPULAS and q in SUBJECTS):
            return 0.92
        return 0.05
    if w == 'that':
        if p == 'just':
            return 1.45
        if p in COPULAS:
            if any(s in FRAMES for s in previous):
                return 1.33
            return 0.68 if q == 'it' or q in MODALS else 0.40
        if p in EVALUATIONS | {'better', 'not', 'intended', 'follows', 'except'}:
            return 0.67
        return 0.035
    if w == 'if':
        if p == 'what':
            return 1.63
        if p in {'wonder', 'matter', 'know'}:
            return 0.47
        return 0.21 if p in {'even', 'only', 'especially', 'particularly'} else 0.0
    if w == 'when':
        if p in {'especially', 'particularly', 'except'}:
            return 0.95
        return 0.26 if adjective(p) else 0.09
    if w == 'be':
        if p in {'could', 'may', 'might', 'must'} and q in {'it', 'there'}:
            return 0.45
        return -0.06 if p == 'would' else 0.0
    if w in {'about', 'like'}:
        if p in {'how', 'what'}:
            return 0.75 if w == 'about' else 0.0
        if p in COPULAS:
            if q in SUBJECTS:
                return 0.48 if w == 'about' else 0.41
            return 0.13 if w == 'about' else 0.07
        return 0.0
    if w == 'of':
        head = generic_noun(p)
        if head in KINDS | PARTS | {'source', 'means'} and adjective(q):
            return -0.16
        salient = p in {'importance', 'significance', 'issue'}
        if salient or (p == 'matter' and q == 'the'):
            return 0.74
        if head in KINDS | {'means', 'piece', 'species', 'source', 'place'}:
            return 0.11 if head == 'kind' and q == 'the' else -0.21
        quantities = {'one', 'each', 'both', 'some', 'most', 'any', 'all', 'many'}
        if p in RELATIONS | quantities:
            return 0.11
        return -0.05 if p == 'number' else -0.014

    noun = generic_noun(w)
    if noun == 'time' and p in {'this', 'that'}:
        return 0.37
    if noun in GENERIC:
        if noun == 'way' and p in {'the', 'this', 'that', 'same'}:
            return 0.13
        if adjective(p) or p == 'fun':
            if noun in MANNER | KINDS | PARTS:
                if any(s in INDEFINITE for s in previous):
                    return -0.55
                return -0.28 if noun in PARTS else -0.19
            return -0.10
        if noun == 'part' and p == 'as':
            return -0.43
        if p in {'a', 'an', 'another'}:
            if noun in KINDS:
                return -0.68
            if noun in MANNER | PARTS:
                return -0.59
            return -0.31
        return -0.17 if noun in PARTS else -0.02
    if w in EVALUATIONS:
        if p in {'a', 'an'}:
            return -0.43
        if p in COPULAS and q == 'it' and w not in {'possible', 'necessary'}:
            return 0.23
    if w in {'possible', 'necessary'} and p in COPULAS | {'as'}:
        return -0.21
    if w in {'maybe', 'perhaps', 'always', 'never'}:
        return 0.14
    if w == 'is' and p in FRAMES:
        return 0.43
    if w in {'a', 'the'} and p in COPULAS and q == 'it':
        return 0.28
    return 0.0


