    doc = prefix.document_ids[-1]
    history = carry[1] if carry is not None and carry[0] == doc else ()
    token = prefix.token_strings[-1]
    value = predict(token, history)
    return (doc, (*history[-7:], token)), value

"""Approximate a negative response to rt spelling, not a topic or meaning.

Short rt fragments, especially i/urt and capital RT, get large negative
values. Split r + t and short continuations are recognized too; longer
fragments and the th digraph weaken the response. Latin/Greek/Cyrillic
spellings are transliterated and NUL padding is ignored. Two additional
syllable rules cover Japanese long-vowel + to and Korean teu. Other tokens
get zero. The preceding-token state resets at document boundaries.
"""
import math
import regex
from anyascii import anyascii

READS = ()
ALPHABET = regex.compile(r'[\p{Latin}\p{Greek}\p{Cyrillic}]')


def letters(text):
    text = text.replace('\x00', '')
    return (anyascii(text) if ALPHABET.search(text) else text).lower()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    low = letters(token)
    value = 0.0
    if previous.endswith('r') and low.startswith('t'):
        n = len(low)
        if n <= 3:
            preceding = previous[-2:-1]
            if not preceding:
                strength = 7.0
            elif preceding in 'aiuy':
                strength = 4.8
            else:
                strength = 3.0
        else:
            strength = 0.7 * math.exp(-(n - 4))
        if low in ('th', 'ths'):
            strength *= 0.25
        value = -strength
    elif 'rt' in low and not token.startswith('<|'):
        left, right = low.strip().split('rt', 1)
        if len(left) <= 1:
            strength = {'a': 1.5, 'e': 1.1, 'i': 3.3,
                        'o': 0.9, 'u': 3.5}.get(left, 1.5)
            if token[0].isspace():
                strength *= 0.4
            if token.strip().isupper():
                strength = 4.8 if not left else strength * 1.4
                if token[0].isspace():
                    strength *= 0.67
        else:
            strength = 0.7 * math.exp(-0.7 * (len(left) - 2))
            if not any(v in left for v in 'aeiouy'):
                strength = 0.08
            if token[0].isspace():
                strength *= 0.5
        value = -strength * (0.8 if right else 1.0)
        value *= math.exp(-0.7 * max(0, len(right) - 1))
    elif previous.endswith('rt') and token and token[0].isalpha():
        value = {1: -1.1, 2: -0.6}.get(len(low), -0.15)
    elif token == 'ート':  # Japanese long vowel followed by "to".
        value = -0.75
    elif token == '트':  # Korean syllable "teu".
        value = -0.55
    return (doc, low), value

"""Approximate a year-like-number feature from digit position and context.

Track contiguous ASCII digits. A 19/20 prefix gets a negative signal on
its second digit, strengthened by date and citation contexts. Four-digit
numbers from 1500 through 2099 get a positive completion signal, with
century-dependent strength. Decimal and code boundaries weaken it.
