YEAR_WORDS = {'in', 'since', 'from', 'between', 'during', 'until', 'through',
              'of', 'the', 'year', 'years', 'born', 'died'}


def context(before, century):
    """Return the strength of a century prefix and of a completed year."""
    z = before.rstrip()
