        abbreviation = len(z) > 1 and z[-2].isalpha()
        return (0.8, 1.0) if abbreviation else (0.05, 0.55)
    if c in ':/-':
        return 0.3, 0.65
    if c in '–—':
        return 0.5, 0.9
    if c in '=+<>_{});' or (spaced and c.isdigit()):
        return 0.2, 0.7
    if c == ',' and not spaced:
        return 0.2, 0.7
    if not spaced and c.isascii() and c.isalpha():
        return 0.35, 0.65
    strength = 1.0 if century == 19 else 0.65
    if not c.isascii() and (c.isalpha() or c in '，。、「'):
        strength += 0.20
    if word in YEAR_WORDS:
        strength += 0.40
    elif word in MONTHS:
        strength += 0.15
