            century = int(digits[:2])
            strength, completion = context(before, century)
            if len(digits) == 2 and century in (19, 20):
                value = -strength
            elif len(digits) == 4:
                decade = int(digits[2])
                if century == 20:
                    value = max(0.05, 0.85 - 0.07 * decade)
                elif century == 19:
                    value = 0.38 + 0.055 * decade
                elif century == 18:
                    value = 0.24 + 0.025 * decade
                elif 15 <= century <= 17:
