"""A nose/nasal spelling family, including adjacent-token completions.

Strong negatives cover nose, nasal, 鼻, and Cyrillic нос; weaker negatives
cover nostril/nail pieces and similar nasal-sibilant fragments. These are
spelling rules, not a general body-part classifier. Short Arabic t clusters
and Hungarian 'azt' form a separate positive family. Other tokens are quiet,
with a small offset at document starts. Only the last token is remembered.
"""
from functools import lru_cache
import re
from anyascii import anyascii

READS = ()

@lru_cache(maxsize=32768)
def latin(text):
    return anyascii(text).lower()


def signal(previous, token):
    raw = token.strip()
    s, p = latin(raw), latin(previous).rstrip()
    cyrillic = bool(re.search('[а-яё]', raw.lower()))
