        return -9.0
    if s == 'nose':
        return -9.6 if raw[:1].isupper() else -13.8
    if s == 'nasal':
        return -9.5
    if s in ('nail', 'nails', 'nostr'):
        return -2.4
    if not token[:1].isspace():
        # Completing a nose-family spelling at a token boundary.
        if token == 'SE' and previous.endswith(('NO', 'NE')):
            return -11.3
        if p.endswith('nas') and s in ('e', 'en', 'al', 'ally'):
            return -10.5
        if p.endswith('nostr') and s in ('il', 'ils'):
            return -2.9
        if p.endswith('nar') and s == 'iz':
            return -12.0
        if p.endswith('ne') and s == 'z':
            return -3.5
        if p.endswith('nos') and s in ('y', 'ing'):
            return -7.0
        if cyrillic and previous.lower().endswith(('но', 'не')):
            if raw.lower() in ('с', 'си', 'ся'):
                return -7.3
        if p.endswith('n'):
            if cyrillic and raw.lower() == 'ос':
                return -10.4
            if cyrillic and raw.lower().startswith(
                ('ес', 'ез', 'из', 'оз', 'ас', 'ож')
            ):
                return -3.7
            if not cyrillic and s == 'ose':
                return -10.8
            if s in ('ail', 'ails', 'ailing'):
                return -4.5
            if s == 'ase' and p.strip() == 'n':
                return -10.5
