        if len(raw) == 2 and 'ت' in raw and previous.endswith(('ا', 'إ', 'أ', 'آ')):
            return 4.5
    if cyrillic and s in ('nos', 'nes', 'nesti'):
        return -4.1
    if s in ('nos', 'nas', 'naz', 'nez', 'niz', 'nes'):
        if token[:1].isspace() and (not cyrillic or s == 'naz'):
            return -1.8
    if re.fullmatch('ا?خت', raw):
        return 2.9
    if re.fullmatch('(?:و?ال)?[ايمت]?ست', raw):
        return 1.0
    if s == 'azt':
        return 8.2
    return 0.3 if previous in ('', '<|endoftext|>') else 0.0


