"""A partial, lexical-continuation approximation for this component.

A new word piece is evidence when it turns an unlikely unfinished stem into
an attested word. Short preceding pieces, WordNet words, fixed expressions,
and hyphenated compounds refine this evidence. Many lexical offsets and
byte-piece effects remain unexplained. Frequencies are the largest
wordfreq frequency across the listed languages. Document starts have a
separate negative offset. COVID-19 and document-title labels are explicit
special cases observed in training. Split UTF-8 characters are not modeled.
"""
from bisect import bisect_left
from functools import lru_cache
from math import log10
from unicodedata import category
import re
import numpy as np
import wordnet
from wordfreq import get_frequency_dict

READS = ()
LANGUAGES = ('en', 'de', 'fr', 'es', 'it', 'pt', 'nl',
             'ru', 'uk', 'pl', 'vi', 'zh', 'ja')
FREQUENCY = {}
for language in LANGUAGES:
    for word, frequency in get_frequency_dict(language).items():
        if word.isalpha():
            FREQUENCY[word] = max(frequency, FREQUENCY.get(word, 0))
WORDS = sorted(FREQUENCY)
TOTALS = np.cumsum([0.] + [FREQUENCY[w] for w in WORDS])


def zipf(word):
    return 9 + log10(max(1e-10, FREQUENCY.get(word, 0)))


@lru_cache(maxsize=100000)
def prefix_mass(fragment):
    lo = bisect_left(WORDS, fragment)
    hi = bisect_left(WORDS, fragment + '\U0010ffff')
    return max(1e-10, float(TOTALS[hi] - TOTALS[lo]))


@lru_cache(maxsize=100000)
def completion(stem, piece):
    whole = stem + piece
    return dict(word_gain=zipf(whole) - zipf(stem), stem_length=len(stem),
                stem_zipf=zipf(stem), word_zipf=zipf(whole),
                dictionary_word=float(bool(wordnet.parts_of_speech(whole))),
                conditional=log10(prefix_mass(whole) / prefix_mass(stem)))


@lru_cache(maxsize=100000)
def expressions(text):
    """Recognize WordNet multiword and hyphenated expressions at the end."""
    words = re.findall(r'[^\W\d_]+(?:-[^\W\d_]+)*', text)[-4:]
    length = titled = hyphenated = 0
    if text and text[-1].isalpha():
        if words and '-' in words[-1]:
            hyphenated = int(bool(wordnet.parts_of_speech(words[-1].lower())))
        for n in (2, 3, 4):
            if len(words) >= n and wordnet.categories(' '.join(words[-n:]).lower()):
                length = max(length, n)
                titled = max(titled, sum(w[0].isupper() for w in words[-n:]))
    return dict(compound_length=length, titled_compound=titled, hyphenated=hyphenated)


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, previous, history = 0, '', ''
    else:
        _, position, previous, history = carry
    token = prefix.token_strings[-1]
    next_carry = (document, position + 1, token, (history + token)[-80:])
    # These two cases describe literal document metadata, not arbitrary IDs.
    if position == 0 and token == 'Title':
        return next_carry, -0.525
    if position == 1 and previous == 'Title' and token == ':':
        return next_carry, -1.985
    if token == '9' and re.search(r'covid-1$', history, re.I):
        return next_carry, 1.2
    f = dict(word_gain=0., dictionary_word=0., stem_length=0.,
             stem_zipf=0., word_zipf=0., conditional=0.)
    stem = re.search(r'[^\W\d_]+$', history)
    if stem and token.isalpha():
        f.update(completion(stem[0].lower()[-32:], token.lower()))
    f.update(expressions(history + token))
    pieces = token.strip() + previous.strip()
    adjoining = (not token.startswith(' ') and token.strip() and previous.strip()
                 and all(category(c)[0] in 'LM' for c in pieces))
    f.update(first=float(position == 0), current_zipf=zipf(token.strip().lower()),
             previous_length=min(12, len(previous.strip())) if adjoining else -1.)
    return next_carry, score(f)


def score(f):
    # Small calibration rules learned on training rows.
    if f['word_gain'] <= 1.07:
        if f['first'] <= 0.0:
            if f['compound_length'] <= 2.0:
                if f['hyphenated'] <= 0.0:
                    return 0.001
                return 0.048
            if f['titled_compound'] <= 1.0:
                return 0.026
            return 0.139
        if f['current_zipf'] <= 7.44:
            if f['current_zipf'] <= -1.0:
                return -0.137
            return -0.266
        return 0.026
    if f['dictionary_word'] <= 0.0:
        if f['stem_length'] <= 7:
            if f['stem_zipf'] <= 4.14:
                return 0.013
            return 0.088
        if f['word_zipf'] <= 4.53:
            return 0.069
        return 0.198
    if f['previous_length'] <= 2.0:
        if f['stem_length'] <= 4.0:
            return 0.043
        return 0.242
    if f['conditional'] <= -0.81:
        return 0.016
    return 0.093

