"""A sparse spelling-fragment predictor, especially for words split near 'il'.

Detached -ville and Scandinavian til/vil fragments are positive; bil/gil/cil
fragments and several -bilization stems are negative. The surrounding letters,
token boundary, and attached suffix matter. Small Cyrillic/Arabic equivalents
are included. Most complete words predict zero; estimates are shrunk toward zero.
"""
import re
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()
MATERIAL_STEMS = ('permeabil', 'solubil', 'compatibil')


@lru_cache(maxsize=8192)
def uncommon(word):
    return zipf_frequency(word, 'en') < 3.5


def consonant_score(letter):
    if letter == 'v':
        return 3.7
    if letter in 'bcg' and letter:
        return -3.5
    if letter in 'xzj' and letter:
        return -2.2
    if letter in 'lmns' and letter:
        return -1.4
    if letter == 't':
        return 0.5
    if letter in 'prhk' and letter:
        return -0.4
    return 0.0


def split_il(previous, token):
    letter = previous[-1:]
    value = consonant_score(letter)
    if token in ('illes', 'illez', 'illet'):
        return 1.1
    if token == 'ille':
        if letter == 'v':
            return 8.5
        if letter == 't':
            return 5.5
        if letter == 'l':
            return 3.8
        if letter in 'uawhspk' and letter:
            return 1.8
        return 0.0
    if token == 'iling' and letter == 't':
        return 4.3
    if token in ('ila', 'ils') and letter == 't':
        return 3.5
    if token == 'illus':
        return -4.0
    if token.startswith('illation'):
        return -1.8
    if token in ('ile', 'iles') or token.endswith('ity'):
        return value * 0.25
    if token.startswith('ili'):
        return value * 0.65
    if token[2:] not in ('', 'l', 'a', 'ar', 'o', 'io', 'it', 'm'):
        value *= 0.25
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, old_word = '', ''
    else:
        _, previous, old_word = carry
    raw = prefix.token_strings[-1]
    token = raw.lower()
    bare = token.strip()
    tail = re.search(r'[a-z]+$', (old_word + token)[-64:])
    word = tail.group() if tail else ''
    value = 0.0
    if token.startswith('il'):
        value = split_il(previous, token)
        if old_word.endswith(('mill', 'mil')):
            value = -6.0  # milliliter / millilitre fragments
    elif len(bare) == 3 and bare.endswith('il'):
        value = 0.7 * consonant_score(bare[0])
        if bare[0] in 'tv':
            value = 1.1
            if raw[:1].isspace():
                value = 3.0
                if raw.strip().islower():
