    elif (bare.isalpha() and bare.endswith('il')
          and uncommon(bare) and 'util' not in bare):
        value = 0.4 * consonant_score(bare[-3])
    if bare in ('abil', 'ibil'):
        value = -2.8
    if bare == 'ville':
        value = 5.8 if not raw[:1].isspace() else 1.0
        if previous.endswith('s'):
            value = 1.2
        if raw.strip().istitle():
            value = 4.0
    elif bare == 'erville' and not raw[:1].isspace():
        value = 4.5
    elif bare in ('till', 'vill') and raw[:1].isspace():
        value = 2.3 if raw.strip().islower() else 1.4
    if word.endswith('multil'):
        value = -2.5  # multi- followed by an l-word, not Scandinavian til
    if word.endswith(MATERIAL_STEMS):
        value = -8.0
    elif old_word.endswith(MATERIAL_STEMS) and token[:1].isalpha():
        value = -5.5
    elif 'facilit' in word:
        value = -2.5 if token.startswith('ation') else -1.5
    elif word.startswith('stabil') and ('iz' in word or 'is' in word):
        value = -2.5 if not token.startswith('izer') else -1.1
    elif previous.endswith('il') and token.startswith(('iz', 'is')):
        value = -2.5
    if 'иль' in token or (token.startswith('ля') and previous.endswith('ти')):
        value = 0.9
    elif token.startswith('е') and previous.endswith('иль'):
        value = 0.7
    elif token.startswith('يل') and previous.endswith('ب'):
        value = -2.2
    return (doc, token, word), float(0.8 * value)

