    '附': -3.6,   # attach
    '幅': -4.0,   # width
    '付': -2.7,   # pay, give
    '赋': -2.7,   # assign
    '符': -2.3,   # sign, tally
    '浮': -1.5,   # float
    '傅': -1.4,   # tutor; surname Fu
