            before = before.decode('utf-8', 'ignore')
            value = -5.0 if before.endswith('都') else -0.4
        elif s == 'ย':
            value = -2.2
        elif s == 'เลย':
            value = -3.0
    return state, value

programs.haiku:
"""layers.1.mlp.down_proj:4829 — the word "say" (and "ay" sounds), read in context.

What it does, in plain terms:
- The bare word " say" (or "Say") is the strongest trigger, but its sign depends on what
  comes before it:
  * after a comma, a dash, "than", "or", "but", "of" or "let's" it is being used as
    "for example / let's suppose" (", say, 5") -> strongly positive;
  * after a subject pronoun or a person/agency ("they say", "I say", "police say") it is
    the reporting verb -> negative;
  * a capitalized "Say" starting a sentence/line (an imperative) -> positive;
  * anything else ("to say", "can say") -> near zero.
- The sound "ay" written as a syllable/name piece ("ay", "aya", "ayan", "Pranay", "Sidee
  tahay") fires moderately, "aye" more strongly; the Persian letter "ای" (ay/ey) too.
- The single character "滑" (as in 润滑, lubricate) fires consistently.
- Everything else is 0.

The rules are read from the previous token only, so the program is causal.
The simple rules capture most of the component's large spikes; a per-token lookup
table would add a few points more of variance but is not a concept.
"""

READS = ()

SAY_FORMS = {" say", "say", " Say", "Say", " SAY", "SAY"}
AY_FORMS = {"ay": 1.4, "aye": 4.9, "aya": 1.4, "ayan": 1.1, "ayas": 1.9, " ay": 2.3, "AY": 0.9,
            "Ay": 1.3, " Hay": 1.3, "ای": 2.5, "ай": 0.7}
EXAMPLE_BEFORE = {",", "than", "or", "but", "–", "-", "'s", "of"}
REPORTING_BEFORE = {"they", "They", "I", "i", "we", "You", "you", "he", "She", "police",
                    "officials", "Authorities", "always", "will"}


def step(carry, prefix, upstream):
    """Predicted activation at the newest token; no state is carried between tokens."""
    tok = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if tok in SAY_FORMS:
        if prev in EXAMPLE_BEFORE:
            return carry, 6.0
        if prev in REPORTING_BEFORE:
            return carry, -3.0
        if tok.strip()[:1].isupper():
            return carry, 4.0
        return carry, 0.2
    if tok == "滑":
        return carry, 4.1
    return carry, AY_FORMS.get(tok, 0.0)

programs.sol:
"""Approximate a boundary and extra-spacing signal.

The main observed events are negative pulses at context starts and positive
pulses on separately tokenized extra whitespace. At starts, calibrate by
letter count, title case, Latin script and a leading blank, with separate
defaults for numbers, punctuation, whitespace and chat-control markers.
Inside text, recognize split whitespace runs and quotes after commas.
Exact lexical amplitudes and longer-context variation are omitted.
"""
import unicodedata

READS = ()


def initial(s):
    if s.startswith('<|'):
        return -7.2 if s == '<|im_start|>' else 0.0
    w = s.strip()
    if not w:
        if s == '\t':
            return -8.1
        if '\n' in s or '\r' in s:
            return -1.3
        return -0.9 if len(s) <= 2 else -3.0
    letters = [c for c in w if c.isalpha()]
    if letters:
        n = len(letters)
        value = -4.5
        if n == 1:
            value += 1.3
        elif n == 2:
            value += 0.7
        if w.istitle():
            value -= 1.3
        if not all('LATIN' in unicodedata.name(c, '') for c in letters):
            value += 0.5
        if s.startswith(' '):
            value -= 1.0
        return value
    if w.isdigit():
        return -2.4
    return -0.15 if s == '.' else -2.0


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    prev = '' if start else carry[1]
    value = 0.0
    if start or prev == '<|endoftext|>':
        value = initial(s)
    elif s == ' ' and prev.endswith(' '):
        value = 2.0 if len(prev) == 1 else 3.4
    elif s == '\t' and prev and not prev.strip('\t'):
        value = 1.6 if len(prev) == 1 else 2.1
    elif s == '\t' and prev == ' ':
        value = 0.9
    elif s == '\xa0' and prev and not prev.strip('\xa0'):
        value = 2.6 if len(prev) >= 3 else 0.4
    elif s in {' "', " '"} and prev.endswith(','):
        value = 1.6
    return (doc, s), value

programs.haiku:
"""layers.1.mlp.down_proj:4830, a down-projection component of layer 1's MLP.

It does two things, both read from the token and the document boundaries.

1. First token of each document (a new document id in the packed row, or the
   row's first token): a large negative value. The size depends on the kind of
   token: about -7 for <|im_start|>, about -5.4 for a capitalised or
   space-led word, about -3.3 for a lowercase word, about -2.4 for a digit and
   about -1.8 for punctuation or whitespace. This is the model's start-of-document
   response, the one that acts like a first-position attention sink.

2. A lone space token directly after an indentation token (a run of spaces or
   tabs with no newline). Tokenisers split the space that precedes a number off
   from the indent, so this is the leading space of a line number or of code in
   an indented block, as in numbered code listings. It is strongly positive:
   about 2 after one space, 3.4 after two or three, 4 after four spaces.
   Tab and no-break-space tokens get a weak +0.5.

Everything else is 0.
"""

READS = ()

INDENT_VALUE = {"  ": 3.35, "   ": 3.45, "    ": 4.0}


def first_value(s):
    c = s.lstrip(" ")[:1]
    if c == "<" and s.startswith("<|"):
        return -7.2
    if c.isalpha():
        return -5.4 if s.startswith(" ") or c.isupper() else -3.3
    if c.isdigit():
        return -2.4
    if s.strip() == "":
        return -1.9
    return -1.7


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = prefix.position
    if t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, first_value(toks[-1])
    if toks[-1] == " " and toks[-2].strip(" \t") == "" and toks[-2] != "":
        return carry, INDENT_VALUE.get(toks[-2], 2.0)
    if toks[-1] in ("\t", "\xa0"):
        return carry, 0.5
    return carry, 0.0

programs.sol:
"""Recognize uncertainty and exceptions, especially 'may/might not'.

The response is local: modals, negated certainty or totality, and partitive
quantifiers, with a few translated negations and opposite-sign comparative
patterns. Strengths are estimated from training text. Only the last three
tokens are remembered, with a reset between documents. Unmatched tokens get
zero; irregular word-piece responses are intentionally omitted.
"""
READS = ()

# Complements that weaken a claim when negated.
NEGATED = {
    'necessarily': 8.4, 'always': 5.0, 'exactly': 4.9,
    'sure': 3.2, 'all': 2.8, 'entirely': 2.8, 'quite': 2.5,
    'every': 2.1, 'everything': 2.5, 'fully': 1.3, 'only': 1.0,
    'the': 0.6, 'many': 2.0, 'much': 1.3,
}
PARTITIVE = {'some': 2.7, 'many': 1.9, 'most': 1.0, 'none': 1.0}
QUANTIFIERS = set(PARTITIVE) | {'few', 'several', 'lot', 'neither'}
NEGATORS = {'not', "n't", 'n’t', "'t", '’t'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        p = pp = ppp = previous_raw = ''
    else:
        _, p, pp, ppp, previous_raw = carry
    # p, pp, ppp are the last three stripped tokens, not a parsed sentence.
    raw = prefix.token_strings[-1].strip()
    w = raw.lower()
    value = 0.0
    if raw in {'may', 'might'}:
        value = 0.72 if w == 'may' else 0.98
        if p in {'i', 'it', 'he', 'she', 'you', 'we', 'they'}:
            value += 0.45
    if w == 'not':
        value = 0.0
        if p in {'may', 'might'}:
            value = 10.8
        elif p in {'maybe', 'perhaps'}:
            value = 7.5
        elif p in {"'m", '’m', "'s", '’s', 'am'}:
            value = 0.9
    if p in NEGATORS:
        value = NEGATED.get(w, 0.0)
        if pp in {'may', 'might'}:
            value = max(value, {'be': 3.2, 'even': 2.1}.get(w, 0.0))
    if w == 'able' and p == 'be' and pp in NEGATORS:
        value = 4.8 if ppp in {'may', 'might'} else 0.6
    if p in {'may', 'might'} and w != 'not':
        value = {'seem': 4.3, 'look': 1.7, 'only': 2.2,
                 'also': -1.2, 'have': 0.7, 'be': -0.15 if p == 'may' else 0.6,
                 'well': 1.3, 'never': 2.5, 'just': 1.0}.get(w, value)
    if w == 'seem' and p in NEGATORS:
        value = 2.0
    # Partial groups of people or things.
    if w == 'of' and p in PARTITIVE:
        value = PARTITIVE[p]
        if previous_raw == 'Some':
            value += 1.8
    if w == 'people' and p in {'some', 'many', 'most'}:
        value = 3.3 + (1.2 if previous_raw[:1].isupper() else 0.0)
    if w == 'cases' and p in {'some', 'many'}:
        value = 2.4
    if p == 'of' and pp in QUANTIFIERS and w in {'us', 'them', 'which', 'whom'}:
        value = 2.3
        if pp == 'lot' and w == 'us':
            value = 4.5
        elif pp == 'many' and w == 'which':
            value = 3.5
    if p == 'of' and pp == 'all' and w == 'whom':
        value = 2.4
    if p == 'no' and w in {'one', 'idea'}:
        value = 1.0
    if w == 'all' and p in {'we', 'you', 'they'}:
        value = 0.8
    # Stronger comparative frequency has the opposite sign.
    if p == 'more' and w == 'often':
        value = -2.3
    if raw == 'Some':
        value = 0.4
    if p in {'more', 'most'} and w.endswith('ly'):
        value = -1.2
    # Translations of negated frequency, totality and certainty.
    if w == 'sempre' and p in {'non', 'nem'}:
        value = 5.5
    if (p, w) in {('nicht', 'ganz'), ('не', 'все')}:
        value = 2.4
    if w == '不一定':
        value = 8.0
    if p.endswith('不') and w in {'一定', '一定的'}:
        value = 9.5 if w == '一定' else 4.5
    if w.startswith('并不'):
        value = 1.5 if w == '并不' else 3.0
    if p.endswith('不') and w == '完全':
        value = 3.5
    return (doc, w, p, pp, raw), value

programs.haiku:
"""Hedged negation and partial quantity (layer 1 MLP, component 4831).

What it responds to, in plain terms: words that soften or narrow a claim.
  * "not" right after a possibility modal: "may not", "might not" (strongest).
  * the adverb after a negation that makes it partial: "not necessarily",
    "don't always", "not exactly", "not all", "not sure".
  * the word after a partitive quantifier: "some of", "most of", "some people",
    "some of which", "most of us".
  * the modals "may" and "might" themselves, weakly.
Everything else predicts 0. The program looks only at the current token and the
one or two tokens before it, so it needs no state.
"""

READS = ()

MODALS = {"may", "might"}
NEGATORS = {"not", "n't", "'t", "’t"}
PARTIAL_ADVERBS = {"sure", "exactly", "all", "quite", "always", "really", "entirely",
                   "exclusively", "altogether", "completely"}
QUANTIFIERS = {"some", "most", "many", "all", "none", "one", "several", "both", "each", "any"}
PRONOUNS = {"which", "whom", "us", "them"}


def step(carry, prefix, upstream):
    tokens = prefix.token_strings
    ids = prefix.token_ids
    docs = prefix.document_ids
    if len(ids) < 2 or docs[-2] != docs[-1]:
        return None, 0.0
    word = tokens[-1].strip().lower()
    prev = tokens[-2].strip().lower()
    same_doc2 = len(ids) > 2 and docs[-3] == docs[-1]
    prev2 = tokens[-3].strip().lower() if same_doc2 else ""

    if word == "not" and prev in MODALS:
        return None, 10.5
    if prev in NEGATORS:
        if word.endswith("necessarily"):
            return None, 8.5
        if word in PARTIAL_ADVERBS:
            return None, 3.5
    if prev == "not" and prev2 in MODALS:
        return None, 2.5
    if word == "of" and prev == "some":
        return None, 3.0
    if word == "of" and prev in ("most", "many"):
        return None, 1.3
    if prev == "of" and prev2 in QUANTIFIERS and word in PRONOUNS:
        return None, 2.5
    if word == "people" and prev in ("some", "many", "most"):
        return None, 3.5
    if word == "cases" and prev in ("some", "most"):
        return None, 2.5
    if word in MODALS:
        return None, 0.9
    return None, 0.0

programs.sol:
"""Approximate a mixed lexical/opening response, not a general reasoning rule.

The large, rare positive is `issue` in a serialized issue-comment opener.
Document beginnings are mostly negative; elementary mathematical vocabulary
and English contraction endings have smaller positive responses. A colon
in a document-initial Title: header is strongly negative. Unmodelled
lexical and contextual variation is replaced by a small background value.
"""
from functools import lru_cache
import wordnet

READS = ()

# An elementary mathematics glossary, matched through WordNet's inflections.
MATH = set('''number integer digit prime zero positive negative sum product
ratio fraction numerator denominator square root side axis angle line slope
vertex edge term derivative integral distance coordinate mod divide times
solution equation variable'''.split())
CODE_OPENERS = set('''import package using include define pragma ifndef
class def const typedef module'''.split())


@lru_cache(None)
def lexical(token):
    word = token.strip().lower()
    plain = word.lstrip('-')
    mathematical = plain in MATH or any(
        base in MATH for base in wordnet.base_forms(plain)
    )
    value = 0.004
    if mathematical and token.strip().islower():
        # Whole words in prose, versus fragments inside identifiers.
        value = 0.085 if token[:1].isspace() else 0.035
        if word in {'-axis', '-digit'}:  # x-axis, three-digit, etc.
            value = 0.25
    if word[:1] in {"'", '’'}:
        ending = word[1:]
        if ending in {'m', 're', 've', 'll', 'd'}:
            value = 0.12
        elif ending == 't':
            value = 0.07
        elif ending == 's':
            value = 0.03
    if word and all(c in '⁰¹²³⁴⁵⁶⁷⁸⁹' for c in word):
        value = 0.11
    if word in {'%', '‰', '°'}:
        value = 0.08
    return value


def opening(token):
    word = token.strip()
    if word == 'Title':
        return 0.018
    if token.startswith('<|'):
        return -0.21
    if word.isdecimal():
        return 0.10
    if not word:
        return -0.08 if '\n' in token else -0.15
    if word.lower().lstrip('#') in CODE_OPENERS:
        return -1.05
    if word.isalpha():
        if not word.isascii():
            return -0.14
        return -0.46 + 0.28 * token.startswith(' ') + 0.15 * word.isupper()
    return -0.25 if all(not c.isalnum() for c in word) else -0.49


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    first = carry is None or carry[0] != doc
    position, tail = (0, '') if first else (carry[1] + 1, carry[2])
    value = opening(token) if first else lexical(token)
    if position == 1 and tail == 'Title' and token == ':':
        value = -2.886
    if token == 'issue':
        if tail.endswith('<issue_start><'):
            value = 1.14
        elif tail.endswith('<'):
            value = 0.195
    elif token == '>Title' and tail.endswith('<issue_start><issue_comment'):
        value = 0.26
    elif first and token == '<':
        value = -0.393
    return (doc, position, (tail + token)[-64:]), value

programs.haiku:
"""Layer-1 MLP down-projection, component 4835: a document-opener feature with a weak
math/contraction tail.

Inside a document this component is nearly silent. Its large effect is at the first token
of each document (the token right after <|endoftext|>, or the first token of a packed row,
where the model resets attention). There it writes a signed value that depends on the kind
of token that opens the document:

- question or instruction openers (`What`, `Is`, `On`, `Generate`) are strongly negative;
- code, markup and punctuation openers (`using`, `#include`, `import`, `#`, `/*`, `,`) are
  negative;
- capitalised prose openers and lowercase continuations are mildly negative;
- digit openers are near zero or slightly positive.

Mid-document it adds a small positive value on math vocabulary (digit, numerator,
denominator, axis, roots, diagonal, ...), on the contraction endings 'm, 't, 've, 're, 'll,
and on the superscripts ² ³ and the degree sign °. Everything else is 0.
"""

READS = ()

QUESTION_OPENERS = {"What", "Is", "Are", "On", "Generate", "How", "Why", "Who", "When", "Do",
                    "Does", "Can", "Translate", "Write", "Explain", "Describe"}
CODE_OPENERS = {"using", "import", "package", "theorem", "const", "class", "int", "char",
                "use", "CREATE", "include", "def", "public", "private", "namespace", "return",
                "function", "var", "let", "from"}
CODE_SYMBOLS = ("#", "/*", "//", "{", "<", "@", "\\", "--", ",")
MATH_STEMS = ("digit", "numer", "denomin", "axis", "coordinat", "root", "diagonal", "side",
              "zero", "minus", "negativ", "modul", "decimal", "quadratic", "vertic", "integer",
              "prime")
CONTRACTIONS = {"'m", "'t", "'ve", "'re", "'ll", "’m", "’t", "’ve", "’re", "’ll"}
SUPERSCRIPTS = {"²", "³", "°"}


def opener_value(token):
    word = token.strip()
    if word in QUESTION_OPENERS:
        return -0.9
    if word in CODE_OPENERS or word.startswith(CODE_SYMBOLS):
        return -0.5
    if word.isdigit():
        return 0.1
    if word[:1].isupper():
        return -0.35
    return -0.24


def tail_value(token):
    word = token.strip()
    if word in CONTRACTIONS or word in SUPERSCRIPTS:
        return 0.12
    if any(stem in word.lower() for stem in MATH_STEMS):
        return 0.15
    return 0.0


def step(carry, prefix, upstream):
    t = prefix.position
    token = prefix.token_strings[-1]
    is_opener = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    if is_opener:
        return carry, float(opener_value(token))
    return carry, float(tail_value(token))

programs.sol:
"""A sparse approximation of local TeX and source-code syntax responses.

Whitespace following a backslash gives a large negative response; command
creation, graphics commands, and multiply escaped quotes give positive ones.
There are also rules for markup, annotations, a few code identifiers,
and a document-initial Title: header.
Ordinary text is approximated by zero, leaving its small lexical responses out.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous, tail = ('', '') if carry is None or carry[0] != doc else carry[1:]
    value = 0.0

    if tail == 'Title' and token == ':':
        value = -6.95
    if previous.endswith('\\'):
        slashes = len(previous) - len(previous.rstrip('\\'))
        if token[:1].isspace():
            value = -0.6
            if slashes == 1:
                if token.isspace():
                    value = -3.0
                elif token.strip().isalpha():
                    value = -3.5
                else:
                    value = -5.5
            if previous == '\\' and token == ' No':
                value = -11.0  # Unified diff's "No newline" annotation.
        elif token.startswith('\\"'):
            value = 1.2
        elif token in ('0', ')', '")', '");'):
            value = -0.5
        elif token in ('new', 'renew', 'provide'):
            value = 2.3
        elif token == 'include':
            value = 2.2
        elif token in ('right', 'left', 'display'):
            value = 0.3
    if tail.endswith(('\\new', '\\renew', '\\provide')) and token == 'command':
        value = 4.6
    if tail.endswith('\\include') and token == 'graphics':
        value = 1.7
    if tail.endswith('\\right') and token.startswith((' )', ' ]', ' }')):
        value = -1.6
    if tail.endswith('\\left') and token.startswith((' (', ' [', ' {')):
        value = -0.4
    if tail.endswith('\\over') and token.isspace():
        value = -0.4

    # TikZ's Bezier-curve clause.
    if previous.strip() == '..' and token == ' controls':
        value = 0.6
    if previous.endswith('<') and token in ('svg', 'defs', 'style', 'rect'):
        value = 3.8
    if previous == ' @' and token in ('typedef', 'internal', 'private'):
        value = 1.0
    if tail.endswith('\\nif') and token == ' __':
        value = 1.0
    if previous == 'if' and token == ' len':
        value = 1.2
    if previous in ('if', ' if') and token == 'else':
        value = 5.5
    if previous == ' end' and token == 'for':
        value = 2.3
    return (doc, token, (tail + token)[-48:]), value

"""Approximate the component with a handful of text constructions.

Backslash-escaped square brackets are the main positive trigger, stronger in
quoted character-name notation. Other escapes receive smaller values. Separate
positive rules cover repeated middle dots, "New England", and Chinese binary
and quaternion compounds, plus numeric 分 expressions. A document's first token
has a small baseline based on its character category; other unrecognized tokens
get zero. State stores the previous token and position, resetting per document.
"""
import unicodedata

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, age = '', 0
    else:
        _, previous, age = carry
    state = (doc, token, age + 1)
    value = 0.0
    if age == 0:
        first = token.lstrip()[:1]
        category = unicodedata.category(first) if first else 'Zs'
        value = {'Nd': 0.5, 'Ll': 0.30, 'Lu': 0.24,
                 'Lo': 0.21}.get(category, 0.24)

    # A backslash may be part of this token or finish the previous one.
    stripped = token.lstrip()
    joined_escape = stripped.startswith('\\')
    escaped = joined_escape or previous.endswith('\\')
    body = stripped.lstrip('\\') if joined_escape else token
    if escaped and body:
        char = body[0]
        if char == '[':
            value = 5.1 if joined_escape else 6.0
            # Quoted character names, as in Mathematica's \\[Alpha].
            if (previous.endswith('"')
                    or (previous.endswith('\\') and '"' in previous)):
                value += 5.5 if not joined_escape else 3.8
            if '\n' in body:
                value *= 0.3
        elif char == '|':
            value = 5.0 if '"' in previous else 1.0
            if body.endswith('\\'):
                value += 1.3
        elif char == ']':
            value = 0.7 if joined_escape else 1.4
        elif char == '$':
            value = 0.3 if joined_escape else 0.65
        elif char.isdigit():
            value = 0.35
        elif char in '<_':
            value = 0.7 if char == '<' else 0.57
        elif char == '{':
            value = 1.0
        elif char == '*':
            value = 1.0 if body.endswith('\\') else 0.15
        elif body in ('u', 'r', 'x'):
            if not joined_escape:
                value = 0.35 if body != 'x' else 0.1
            elif body == 'x' and previous.endswith(("'", '"')):
                value = 1.2
        elif char == '(':
            value = 0.3

    # A repeated interpunct run has a stable, moderate positive response.
    if len(token) >= 2 and not token.strip('·'):
        value = 1.42

    # This geographic compound is a separate, strong lexical response.
    if previous.strip() == 'New' and token == ' England':
        value = 7.2

    # Technical numeral compounds: binary trees/forms and quaternions.
    if previous == '二' and token in ('叉', '元'):
        value = 5.9 if token == '叉' else 4.8
    elif previous == '四' and token == '元':
        value = 6.3

    # Numeric 分: minutes, points, or the denominator in Japanese fractions.
    if previous.isdigit() and token == '分':
        value = 1.0

    return state, value

programs.haiku:
"""Fires on a bare space token that comes right before a number.

Qwen splits digits into single tokens, so the space in "born June 4" is its own
token " " and the digit "4" is the next token. So this component fires on that
space, when the model expects a number to come next. It is strongest right after a
month name or a preposition such as "at", "in", "of" (a date or a quantity is
coming), a bit weaker after punctuation, and weaker still after code operators such
as "=" or "+". It is silent after a digit (the space inside a list of numbers), and
after a line break, real or escaped as "\\n" in code strings.
"""

READS = ()

MONTHS = {" January", " February", " March", " April", " May", " June", " July",
          " August", " September", " October", " November", " December"}
PREPS = {" in", " of", " at", " on", " about", " after", " for", " from", " between",
         " by", " over", " than", " to", " into"}
CODE = {" =", " +", " -", " <", " >", " ==", " +=", " [", " return", ")", "]:"}
PUNCT = {",", ".", ":", ";", ".,", "...", " and", " or", " the", " is", " a"}


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    if len(toks) < 2 or toks[-1] != " ":
        return None, 0.0
    p = toks[-2]
    escaped_newline = p == "n" and len(toks) > 2 and toks[-3].endswith("\\")
    if p.isdigit() or "\n" in p or p in ("'", '"') or escaped_newline:
        return None, 0.0
    if p in MONTHS:
        return None, 1.6
    if p in PREPS:
        return None, 1.4
    if p in PUNCT:
        return None, 1.1
    if p in CODE:
        return None, 0.7
    return None, 0.9

programs.sol:
"""Arabic lam-led word pieces, with weaker responses in Persian.

Short pieces beginning with ل (lam) give a large negative response: these
are often Arabic prepositions or negative particles. Longer pieces are
weaker. Nearby Persian-style letters attenuate the response unless Arabic
vowel marks are present. A trace continues through a following vowel mark
or single Arabic letter. Other text is zero. These are spelling heuristics,
not a grammatical parser; smaller unrelated responses are omitted.
"""
import unicodedata
import regex

READS = ()
PERSIAN_LETTERS = frozenset('پچژگکی')


def lam_strength(word):
    """Approximate strength of short lam prefixes and grammatical words."""
    if word.startswith(('لكن', 'لديك')):
        return 1.0
    if word.startswith('ليس'):
        return 2.5
    if word.startswith('لهذ'):
        return 7.5
    if len(word) > 3 and word not in ('لأنه', 'لذلك'):
        return 0.0
    if word.startswith('لل'):
        return 12.5 if word.startswith('للأ') else 9.3
    if len(word) == 1:
        return 9.8
    second = word[1]
    if second in 'مت':
        strength = 11.6
    elif second == 'ن':  # the negative particle lan
        strength = 14.0
    elif second == 'أ':
        strength = 13.0
    elif second == 'ا':
        strength = 5.1
    elif second == 'ك':
        strength = 5.4
    elif second == 'ي':
        strength = 7.7
    elif second == 'و':
        strength = 4.0
    else:
        strength = 9.4
    decay = 0.5 if second == 'أ' else 0.65
    return strength * decay ** (len(word) - 2)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        history, trace, marked = '', 0.0, False
    else:
        _, history, trace, marked = carry
    token = prefix.token_strings[-1]
    word = token.lstrip()
    marks = bool(word) and all(unicodedata.combining(c) for c in word)
    previous_word = history.split()[-1] if history.split() else ''
    previous_base = ''.join(c for c in previous_word
                            if not unicodedata.combining(c))
    initial = (token != word or not history or
               not (history[-1].isalpha() or
                    unicodedata.combining(history[-1]) or
                    history[-1] == '\ufffd'))
    clitic = previous_base in ('و', 'ف')
    value, next_trace = 0.0, 0.0
    particle = word[1:] if word.startswith('ول') else word
    if particle.startswith('ل') and (initial or clitic):
        strength = lam_strength(particle)
        if word.startswith('ول') or clitic:
            strength *= 0.9
        if initial and token == word:
            strength *= 1.2
        if (any(c in PERSIAN_LETTERS for c in history[-80:]) and
                not any(unicodedata.combining(c) for c in history[-40:])):
            strength *= 0.35
        value = -strength
        if particle in ('ل', 'لل', 'لا'):
            next_trace = value
    elif word == 'الل' and initial:
        value, next_trace = -2.4, -2.4
    elif trace and token == word:
        if marks:
            value, next_trace = 0.85 * trace, 0.9 * trace
        elif len(word) == 1 and regex.fullmatch(r'\p{Script=Arabic}', word):
            fraction = 0.8 if marked or previous_base == 'ول' else 0.2
            if word == 'ج':
                fraction = 0.5
            value = fraction * trace
            if word == 'ل':
                next_trace = 0.5 * value
    return (doc, (history + token)[-100:], next_trace, marks), value

"""Approximate a mixture of opening cues and attached numerals.

Opening Title: (especially its colon), using/namespace, nonbreaking spaces,
fullwidth percent, spaced period, and opening 12 have special responses.
Technical names ending in 2 or 5 respond more strongly than generic attached
numerals; Roman II and split English forms of five/fifteen also respond.
Paired middle dots and later 'import' are positive. Decimal digits have small
calibrated offsets; most other text is zero. Lexical fluctuations are omitted.
"""
import re
import inflect

READS = ()

# Familiar versioned libraries, protocols, and computing standards.
COMPUTING_TWO = frozenset({
    'cv', 'urllib', 'oauth', 'sqlite', 'jinja', 'apache', 'web', 'http',
})
COMPUTING_FIVE = frozenset({'md', 'html', 'es', 'pyqt', 'hdf'})
# Cardinal, ordinal and plural forms, generated by English inflection rules.
english = inflect.engine()
FIVE_FORMS = set()
for number in (5, 15):
    for name in (english.number_to_words(number),
                 english.number_to_words(english.ordinal(number))):
        FIVE_FORMS.update((name, english.plural(name)))

# Calibrated decimal-digit offsets; 2 and 5 have contextual rules below.
DIGIT_BACKGROUND = (0.006, -0.004, 0, -0.010, -0.008,
                    0, -0.010, -0.003, -0.018, 0.026)
OPENING_DIGITS = (0, 0.10, -0.405, 0.055, -0.159,
                  -0.144, 0.088, 0.298, 0.011, -0.059)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous, first, tail = 0, '', token, ''
    else:
        _, position, previous, first, tail = carry
        position += 1

    match = re.search(r'[A-Za-z]+\Z', tail)
    word = match[0] if match else ''
    attached = bool(word) and token[:1].isascii() and token[:1].isalnum()
    value = 0.0

    if token == '··':                 # paired middle-dot separators
        value = 2.21
    elif position == 0:
        if token == 'using':
            value = 1.41
        elif token == 'namespace':
            value = 1.58
        elif token == 'Title':
            value = 0.404
        elif token.isspace() and '\u00a0' in token:
            value = 1.1
        elif token == '％':
            value = 1.25
        elif token == ' .':
            value = 1.45
        elif len(token) == 1 and token in '0123456789':
            value = OPENING_DIGITS[int(token)]
    elif position == 1 and first == 'Title' and token == ':':
        value = 3.224
    elif position == 1 and first == '1' and token == '2':
        value = 1.264
    elif token == '2':
        if word.lower() in COMPUTING_TWO:
            value = 0.95
        elif attached:
            value = 0.40 if word.isupper() else 0.23
        elif previous == '_':
            value = 0.16
        else:
            value = -0.01
    elif token == '5':
        if word.lower() in COMPUTING_FIVE or word.lower().endswith('hdf'):
            value = 0.90
        elif attached:
            value = 0.25
        else:
            value = -0.06 if previous == '.' else 0.06
    elif token.strip() in ('II', 'ii'):
        value = 0.31 if token[:1].isspace() else 0.19
    elif attached and (word + token).lower() in FIVE_FORMS:
        value = 1.65 if token.lower() == 'ives' else 0.74
    elif token.strip().lower() in FIVE_FORMS:
        value = 0.10
    elif token == 'import':
        value = 0.13
    elif len(token) == 1 and token in '0123456789':
        value = DIGIT_BACKGROUND[int(token)]

    return (doc, position, token, first, (tail + token)[-48:]), float(value)

"""Sparse responses to formula notation, time words, and document starts.

Negative events: selected mathematical Greek letters, the escape before a
scalable TeX delimiter, and legacy square-bracket fragments in PDF text.
Greek word runs suppress the symbol rules.
TeX multiplication and limits commands are positive. The colon of an initial
"Title:" header is strongly negative. Other document starts get a small
word-shape-dependent offset; ordinary text is otherwise near zero.
"""
import re
import regex

READS = ()

# Top, extension and bottom of square brackets in two legacy font encodings.
# Adobe names: github.com/adobe-type-tools/agl-aglfn/blob/master/glyphlist.txt
SQUARE_BRACKET_PARTS = frozenset(
    '\uf8ee\uf8ef\uf8f0\uf8f9\uf8fa\uf8fb'
    '\uf0e9\uf0ea\uf0eb\uf0f9\uf0fa\uf0fb'
)
GREEK = {'τ': -1.35, 'η': -0.3, 'ξ': -0.8, 'ρ': -0.3, 'ζ': -1.5}
TEX_GREEK = {'tau': -1.4, 'eta': -0.6, 'xi': -1.25, 'rho': -0.25,
             'epsilon': -0.26}


def initial_value(token):
    word = token.strip()
    if token.startswith('<|'):
        return 0.04
    if not token.isascii():
        return 0.06
    if not word:
        return 0.27
    if word.isdigit():
        return 0.23
    if not any(c.isalnum() for c in word):
        return 0.4
    if not token.startswith(' ') and word[0].isupper():
        return 0.27
    return 0.39 if word[0].isupper() else 0.35


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    raw = prefix.token_bytes[-1]
    fresh = carry is None or carry[0] != doc
    old = b'' if fresh else carry[1]
    token = raw.decode('utf-8', 'replace')
    history = old.decode('utf-8', 'replace')
    joined = old + raw
    end = joined.decode('utf-8', 'replace')[-1:]
    value = 0.0
    if fresh:
        value = initial_value(token)
    elif token == ':' and old == b'Title':
        value = -4.71
    elif end in SQUARE_BRACKET_PARTS:
        value = -2.0 if end in '\uf8f0\uf8fb\uf0eb\uf0fb' else -3.1
    elif token == '\\' and re.search(
            r'\\(?:left|right|big|Big|bigg|Bigg)$', history):
        value = -2.85
    elif token == 'eta' and history.endswith('\\z'):
        value = -2.5
    elif history.endswith('\\'):
        value = TEX_GREEK.get(token, 0.0)
        if token == 'times':
            value = 1.0
        elif token == 'limits':
            value = 1.3
    elif token.strip().lower() in ('time', 'times'):
        value = -0.2 if token.strip()[0].isupper() else (
            -0.08 if token.strip() == 'times' else -0.16)
    letter = token.strip()
    if raw and 0x80 <= raw[0] < 0xc0:
        letter = end  # A byte token finishing a Greek character.
    if not fresh and letter in GREEK:
        prose = (regex.search(r'\p{Script=Greek}{3,}', history[-80:])
                 or regex.search(r'\p{Script=Greek}{2}$', history))
        if not prose:
            value = GREEK[letter]
            if token.startswith(' '):
                value *= 0.65
    return (doc, joined[-256:]), value

"""An opening-quotation and inline-formatting signal.

Opening backticks and quotation marks get large positive values. Closing marks,
code strings and ordinary text get smaller ones. Punctuation and the last 256
characters distinguish these uses; document boundaries reset that context.
There are also weaker rules for math notation, emphasis, and inline tags.
This leaves word-specific effects and fine variations in magnitude unexplained.
"""
import re
import regex

READS = ()

OPEN_QUOTES = {
    '“': 1.03, '‘': 1.93, '«': 2.05, '‹': 2.0, '„': 2.31,
    '「': 1.62, '『': 2.39, '《': 1.21, '【': 0.53,
}
INLINE_TAGS = {'i', 'b', 'em', 'strong', 'u', 'cite', 'code', 'a',
               'span', 'small', 'sub', 'sup'}
TEX_FORMAT = {
    'mathrm', 'mathbf', 'mathit', 'mathcal', 'mathbb', 'mathsf', 'mathtt',
    'text', 'textrm', 'textbf', 'textit', 'emph', 'hat', 'widehat',
    'tilde', 'widetilde', 'bar', 'overline', 'underline', 'vec',
    'box', 'boxed', 'hbox', 'mbox', 'Vert',
}


def predict(token, before):
    s = token.strip()
    previous = before.rstrip()[-1:] or '\n'
    recent = before[-100:]
    code = bool(re.search(r'[=;{}]|\w_\w|\b(return|import|const|var|case)\b',
                          recent))
    if s.startswith('<|'):
        return 0.001
    for quote, value in OPEN_QUOTES.items():
        if quote in token:
            return value
    if s in {'»', '”', '’'} and token[:1].isspace():
        return 1.23
    if before.endswith('<') and s in INLINE_TAGS:
        return 1.37
    # A curly double quote written as escaped UTF-8 bytes.
    if s == 'c' and re.search(r'\\x[eE]2\\x80\\x9$', before):
        return 5.31
    command = re.search(r'\\([A-Za-z]+)$', before + token)
    if command and token.isalpha():
        if command[1] == 'left':
            return 1.0
        if command[1] in TEX_FORMAT:
            return 0.8
    if s.startswith('/*') or (s.startswith('**') and before.endswith('/')):
        return 0.74
    inline_tag = r'<(i|b|em|strong|u|cite|code|a|span|small|sub|sup|x[a-z])'
    if s == '>' and re.search(inline_tag + r'( [^<>]*)?$', before):
        return 1.99
    if s.startswith('<') and not s.startswith(('</', '<!', '<=', '<<')):
        return 0.34 if token[:1].isspace() else 0.001
    if s.startswith(('\\(', '\\[', '$\\')):
        return 0.97
    if s.startswith('$$'):
        opening = token[:1].isspace() or not before or before[-1:].isspace()
        return 0.98 if opening else 0.05
    if s.startswith('$') and (token[:1].isspace() or not before or
                              before[-1:].isspace()):
        return 0.83 if re.search(r'\\|\$[^$]+\$', recent) else 0.31

    for quote in ('`', '"', "'"):
        if quote not in token:
            continue
        i = (token.rfind(quote) if quote != '`' and s not in ('""', "''")
             else token.index(quote))
        leader, tail = token[:i], token[i + 1:]
        if any(c.isalnum() for c in leader):
            return 0.001
        if quote != '`' and tail.startswith(quote):
            return 0.49
        unescaped = leader.rstrip('\\')
        opening = bool(unescaped and (unescaped[-1:].isspace() or
                                      unescaped[-1:] in '=([{,:'))
        opening |= not before or before[-1:].isspace() or before[-1:] in '=([{,:'
        if quote == '`' and not opening and regex.search(
                r'[\p{Script=Han}\p{Script=Hiragana}\p{Script=Katakana}]$', before):
            return 4.31
        if not opening:
            return 0.28 if quote == '`' else 0.02
        if quote != '`' and any(c.isalnum() for c in tail):
            return 0.44
        if quote != '`' and '\\' in leader:
            return 1.04 if token[:1].isspace() else 0.18
        if quote == '`':
            if leader.strip() and not token[:1].isspace():
                return 0.14
            if s.startswith('```'):
                return 0.99
            if s.startswith('``'):
                return 0.94
            return 0.47 if '\xa0' in recent or previous in '`{};' else 2.26
        double = quote == '"'
        if leader.strip(' \t\r\n\\'):
            return 0.13 if double else 0.04
        if previous in '=+<>|&':
            return 0.09 if double else 0.21
        if previous in ':,([{':
            return 0.39 if double else 0.34
        if code:
            return 0.79 if double else 0.92
        return 1.18 if double else 1.8

    if s == ',,' and token[:1].isspace():
        return 2.31
    if '*' in s and not s.startswith(('*/', '/*')):
        leader = token[:token.index('*')]
        if leader.strip() in ('(', '[') or before.endswith('['):
            return 1.21
        if leader.strip():
            return 0.001
        if not (token[:1].isspace() or not before or before[-1:].isspace()):
            return 0.13
        bold = s.startswith('**')
        if code or previous.isdigit() or previous in '),=+*/':
            return 1.48 if bold else 0.22
        line = re.split(r'\n|\\n', before)[-1]
        if not line.strip() or line.rstrip().endswith('*'):
            return 1.95 if bold else 0.26
        return 1.66 if bold else 1.78
    if s == '{@':
        return 1.62
    return 0.09 if s in ('|', '||') else 0.001


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    return (doc, (before + token)[-256:]), predict(token, before)

programs.haiku:
"""Opening quotation marks and markup openers (down_proj component 4844, layer 1).

What it does: it fires on the token that OPENS a quotation or a formatted span, such as
a quote mark that begins a quoted phrase, a backtick that begins a code name, a bold
marker that begins emphasis, or a dollar sign that begins maths. The size of the response
depends on the kind of opener and on the text just before it:
  * a quote or marker that starts a new word (leading space) fires more than one
    attached to a previous character (e.g. the quote in  `"key": "value"`);
  * after a word or sentence end (ordinary prose) it fires more;
  * after code or JSON punctuation (`=`, `+`, `":`, `(`) it fires less.
Everything else predicts 0. Values are typical activations from a sample of training text.
"""

import re

READS = ()

# Typical activation for each opener, from a sample of text.
CURLY_QUOTES = {" “": 1.3, "“": 0.9, " „": 2.5, "„": 1.0, " «": 1.8, "«": 1.8,
                " ‘": 1.8, "‘": 1.8, " 「": 1.4, "「": 1.6, "『": 2.0, "《": 1.3}
STRAIGHT_QUOTES = {' "': 0.7, " '": 0.7, ' \\"': 0.9, '\\"': 0.45, '"': 0.12, "'": 0.07}
BACKTICKS = {" `": 1.7, "`": 0.4, " ``": 1.2, "``": 0.7, ":`": 2.7, " ```": 1.3, "```": 1.0}
EMPHASIS = {" **": 2.4, "**": 0.4, " *": 0.3, "*": 0.2}
DOLLARS = {" $": 0.6, " $$": 1.3, " $\\": 1.0, "$\\": 1.2, " \\(": 1.1, "$": 0.1, "$$": 0.1}
OPENERS = {**CURLY_QUOTES, **STRAIGHT_QUOTES, **BACKTICKS, **EMPHASIS, **DOLLARS}


def context_factor(prev):
    """How the text just before the opener looks: prose gives more, code or JSON less."""
    if re.search(r"[A-Za-z]", prev) and not re.search(r"[\"'`=+<>(){}\[\];:,|&]", prev[-1:]):
        return 1.3  # after a word
    if re.search(r"[.!?]\s*$", prev):
        return 1.1  # after the end of a sentence
    if re.search(r"[\"'`]", prev):
        return 0.5  # right after another quote mark, as in "key": "
    if re.search(r"[=+<>(){}\[\];:,|&]", prev):
        return 0.7  # after code punctuation
    return 0.8  # after whitespace or indentation


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token not in OPENERS:
        return carry, 0.0
    prev = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else ""
    return carry, OPENERS[token] * context_factor(prev)

programs.sol:
"""Spelling rules for 'whole / put in order', plus vowels following tau.

Negative responses mark 整 (whole, complete, put in order), its compounds,
and split spellings of entire/entier/intero and rectify. Greek iota or eta
following tau gives a positive response; Latin ix following t does too.
Smaller rules cover Korean adjustment/organizing, 正 compounds, and 👨.
These are spelling rules, not a general-purpose semantic classifier.
A byte tail handles characters split across tokens and resets per document.
"""
import unicodedata as ud

READS = ()


def response(token, previous_token, previous_text):
    s = token.strip()
    if '整' in s:
        if s == '整':
            return -8.6
        if any(word in s for word in ('整理', '整治', '整改', '整顿', '整頓')):
            return -5.0  # organizing, correcting, rectifying
        if '完整' in s:
            return -1.5  # completeness
        if s.startswith('整') or '整个' in s or '整個' in s:
            return -3.3  # whole, integrated, and other 整 compounds
        return -2.6      # adjustment / reorganization compounds
    if previous_token.strip() == '整':
        if s in {'體', '体', '備', '备', '肃', '肅', '型', '容'}:
            return -6.5  # completions of whole / preparation / reshaping
        if s and ud.category(s[0]) == 'Lo':
            return -1.1
    if s == '👨':
        return 2.9  # man pictograph, including before skin-tone modifiers
    if previous_text.endswith('조') and s == '정':
        return -2.1  # Korean 조정: adjustment
    if previous_text.endswith('정') and s == '리':
        return -2.0  # Korean 정리: organizing
    if previous_token == '正' and s in {'骨', '直'}:
        return -2.4  # straightening bones / straightness
    if token and not token[0].isspace():
        letters = ud.normalize('NFD', token)
        if all(ud.combining(c) for c in letters[1:]):
            if previous_text.endswith(('τ', 'Τ')):
                if letters[0].lower() == 'ι':
                    return 6.9 if previous_text.endswith('Τ') else 5.0
                if letters[0].lower() == 'η':
                    return 0.5 if len(letters) > 1 else 1.5
        suffix = token.lower()
        root = previous_token.strip().lower()
        if root in {'ent', 'int'} and suffix.startswith(('ire', 'ier', 'ière')):
            return -4.1
        if root == 'enti' and suffix.startswith(('er', 'ère')):
            return -3.0
        if root == 'inter' and suffix in {'o', 'a', 'i', 'e'}:
            return -4.1
        if root == 'rect' and suffix.startswith('if'):
            return -3.9 if suffix.startswith('ifier') else -1.4
        if previous_text.endswith(('t', 'T')) and suffix == 'ix':
            return 3.0
    return -0.0024


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        old_bytes, old_token = b'', ''
    else:
        _, old_bytes, old_token = carry
    before = old_bytes.decode('utf-8', 'ignore')
    joined = old_bytes + prefix.token_bytes[-1]
    token = joined.decode('utf-8', 'ignore')[len(before):]
    value = response(token, old_token, before)
    return (doc, joined[-48:], token), value

"""A partial approximation of Slavic and Persian orthographic responses.

A leaky language estimate compares completed words' dictionary frequencies.
A second, faster estimate counts nearby script-specific letters. These gate
fragment responses; ordinary text otherwise receives approximately zero.
In Slavic contexts, the Latin formula favors short English/German-like
fragments and e/o, and penalizes Czech/Polish word familiarity.
The isolated Cyrillic reversed E, Cyrillic i, Persian sheen/khah, and repeated
middle dots have separate, particularly conspicuous responses.
"""
from functools import lru_cache
import unicodedata
from wordfreq import zipf_frequency

READS = ()
WESTERN = ('en', 'de', 'fr', 'es', 'ro', 'da', 'nb')
SLAVIC = ('cs', 'pl', 'sk')
CYRILLIC_VOWELS = frozenset('аеёиоуыэюяіїє')


@lru_cache(maxsize=65536)
def language_evidence(word):
    western = max(zipf_frequency(word, lang) for lang in WESTERN)
    return tuple(max(-3., min(3., zipf_frequency(word, lang) - western))
                 for lang in SLAVIC)


@lru_cache(maxsize=65536)
def spelling(token):
    word = token.strip().lower()
    names = [unicodedata.name(c, '') for c in word if c.isalpha()]
    return (word, any('LATIN' in n for n in names),
            any('CYRILLIC' in n for n in names),
            sum('ARABIC' in n for n in names))


@lru_cache(maxsize=65536)
def latin_value(token, word):
    # Familiar English/German fragments, uncommon as whole Slavic words.
    def frequency(language):
        return zipf_frequency(word, language) / 7 if word.isalpha() else 0.

    english, german, czech, polish, slovak = map(
        frequency, ('en', 'de', 'cs', 'pl', 'sk'))
    letters = sum(c.isalpha() for c in word)
    length = min(5, letters) / 5
    mid_vowels = min(2, sum(c in 'eo' for c in word))
    value = (.23 * english + .03 * max(czech, polish, slovak)
             - .13 * czech - .12 * polish + .12 * mid_vowels)
    if token.startswith(' '):
        value += (.61 - .66 * length - .35 * czech + .58 * german
                  - .38 * (letters == 1) - .22 * polish
                  + .15 * mid_vowels)
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, '', (0., 0., 0.), 0., 0., 0.)
    _, unfinished, languages, ukrainian, arabic, persian = carry
    token = prefix.token_strings[-1]
    word, latin, cyrillic, arabic_letters = spelling(token)

    # Complete words, rather than individual tokenizer fragments, identify language.
    for char in token.lower():
        if char.isalpha():
            unfinished += char
        elif unfinished:
            if len(unfinished) > 1 and (
                unfinished.isascii() or
                any('LATIN' in unicodedata.name(c, '') for c in unfinished)
            ):
                evidence = language_evidence(unfinished)
                languages = tuple(.85 * a + .15 * b
                                  for a, b in zip(languages, evidence))
            unfinished = ''

    ukrainian = .9 * ukrainian + .1 * sum(c in 'іїєґ' for c in word)
    arabic = .9 * arabic + .1 * arabic_letters
    persian = .9 * persian + .1 * sum(c in 'پچژگ' for c in word)

    value = 0.0
    space = token.startswith(' ')
    if word.count('·') >= 2:
        value = -1.0
    elif cyrillic:
        if word == 'э':
            value = (4.58 if token.strip().islower() else 3.46) if space else 2.8
        elif 'і' in word:
            value = 1.55 if space else .38
        elif space and word and all(c in CYRILLIC_VOWELS for c in word):
            value = 2.85 if ukrainian > .003 else 0.0
        elif ukrainian > .054 and 'и' in word:
            value = -.96
    elif arabic_letters:
        if 'ش' in word:
            if arabic <= 1.49:
                value = -1.67 if persian == 0 else (-3.72 if persian > .081 else -3.04)
            elif len(word) == 1:
                value = -2.18 if arabic <= 1.69 else -.33
        elif 'خ' in word and persian > 0:
            value = -1.2
        elif word == 'ا' and space and persian > 0:
            value = 1.26
    elif latin and max(languages) > .4:
        value = latin_value(token, word)

    carry = (doc, unfinished, languages, ukrainian, arabic, persian)
    return carry, value

"""A coarse word-rarity response, with a separate document-start transient.

Long, uncommon alphabetic spellings get positive values, especially after
punctuation/spacing rather than a letter. Common words and short fragments
get smaller values. Frequency comes from corpus counts, not a model.
This captures broad surface preferences, not individual word preferences.
"""
from functools import lru_cache
from wordfreq import zipf_frequency

READS = ()


@lru_cache(maxsize=32768)
def spelling(s):
    word = s.strip()
    # Larger Zipf frequencies mean more common English spellings.
    frequency = zipf_frequency(word.lower(), 'en') if word.isalpha() else 0.0
    letters = sum(c.isalpha() for c in s) / max(1, len(s))
    return frequency, word.isalpha(), letters


def step(carry, prefix, upstream):
    s = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry != doc
    frequency, alphabetic, letters = spelling(s)
    previous_letter = (not first and prefix.token_strings[-2][-1:].isalpha())

    if first:
        if s == '<|endoftext|>':
            value = -3.67
        elif frequency > 6.53:
            value = -0.067
        else:
            value = -0.24 if s.startswith(' ') else -0.41
    elif len(s) <= 6:
        if frequency <= 3.51:
            value = -0.010 if len(s) <= 4 else 0.060
        else:
            value = -0.034 if frequency <= 6.53 else -0.007
    elif frequency <= 4.18:
        if not alphabetic:
            value = 0.005 if letters <= 0.875 else 0.096
        else:
            value = 0.156 if previous_letter else 0.255
    elif frequency <= 4.72:
        value = 0.031 if previous_letter else 0.133
    else:
        value = -0.039 if previous_letter else 0.017
    return doc, value

"""Approximate a spelling-sensitive nasal-fragment feature.

Positive responses include short 'ning' fragments, 宁 (Ning), and the words
beginning, starting and meaning. Across a token boundary, an n/ng ending
followed by a vowel plus m/g tends negative; another n tends positive.
Short or uppercase fragments have stronger effects than long preceding words.
There is also a small document-start offset. These are training averages, not
a full account of the component's contextual variation.
"""
from functools import lru_cache
from anyascii import anyascii
from opencc import OpenCC
import regex as re

READS = ()
SIMPLIFY = OpenCC('t2s')


@lru_cache(maxsize=32768)
def spelling(text):
    """Transliterate, but do not join Chinese characters into Latin syllables."""
    s = anyascii(text).lower()
    if re.search(r'\p{Script=Han}', text):
        return s, '', SIMPLIFY.convert(text) == '宁'
    tail = s
    if re.search(r'[\p{Hiragana}\p{Katakana}\p{Hangul}]', text):
        tail = tail.rstrip('aeiou')
    return s, tail, False


def response(text, s, previous, ning, previous_caps=False):
    word = s.strip()
    short = len(previous.strip()) <= 4 or previous_caps
    if previous and not text[:1].isspace():
        for stem, ending, value in (
            ('begin', 'ning', 6.25),
            ('start', 'ing', 2.4),
            ('mean', 'ing', 6.2),
        ):
            if previous.endswith(stem) and word == ending:
                return value
    capital = text.strip()[:1].isupper()
    if word == 'starting':
        return 2.45 if capital else 1.89
    if word in {'beginning', 'beginnings'}:
        return 3.72 if capital else 2.61
    if word in {'meaning', 'meanings'}:
        return 2.69 if capital else 1.80
    if word in {'begin', 'begins', 'meaningful'}:
        return 0.15
    if ning:
        return 3.94
    if re.search(r'\p{Script=Han}', text):
        return 0.0
    if text.isascii():
        if re.fullmatch(r'nam|nams', word):
            return -2.2 if not text[:1].isspace() and not capital else -0.7
        if re.fullmatch(r'nag(?:ar|s)?', word):
            return -2.22
        if word == 'nem':
            return -1.05
        if word in {'num', 'nm'}:
            if previous.endswith(('n', 'ng')) and not text[:1].isspace():
                return -3.3
            return -0.7 if not text[:1].isspace() else -0.25
    if re.fullmatch(r'ning(?:s|ar)?', word):
        return 3.82 if short and previous.endswith('en') else 0.94
    if word == 'nung':
        return 0.84
    if re.fullmatch(r'[aeiou]n+ing(?:s)?', word):
        return 0.44
    if text[:1].isspace() or not previous.endswith(('n', 'ng', 'mean', 'start')):
        return 0.0
    if word == 'enum' or re.fullmatch(r'[aeu][mg](?:[aeiou]?[brs]?|ar)?', s):
        if not short:
            return -0.24
        return -2.6 if s[:1] in 'au' else -1.5
    if s in {'m', 'mr', 'ml', 'ma', 'mi', 'mu', 'me'}:
        return -1.02 if short else -0.44
    if s in {'ing', 'ings', 'ingen', 'inger'}:
        if short and previous.endswith('en'):
            return 2.18
        return 1.49 if short else 0.19
    if s in {'in', 'inny'}:
        return 1.04 if short else 0.64
    if s in {'ang', 'un', 'ung', 'ungan', 'ungs'}:
        return 1.34 if short else 1.08
    if len(s) <= 5 and re.match(r'^[ae]n', s):
        return 0.18 if short else 0.07
    if s in {'ar', 'ard', 'aw'}:
        return 0.40 if short else 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    fresh = carry is None or carry[0] != doc
    previous = '' if fresh else carry[1]
    text = prefix.token_strings[-1]
    s, tail, ning = spelling(text)
    previous_caps = False if fresh else carry[2]
    value = response(text, s, previous, ning, previous_caps)
    caps = text.strip().isupper()
    if previous_caps and caps and not text[:1].isspace():
        value *= 1.5
    return (doc, tail, caps), value + (0.23 if fresh else 0.0)

"""Recognize forum counters and reply controls, and document-opening comments.

These are sparse positive responses.  Recent text distinguishes a forum's
Posts/Views labels from prose, and a guillemet distinguishes its Reply button.
Spaced closing punctuation after a number or single-letter expression is
negative, as are familiar English words printed with inter-letter spaces.
Document starts and chat markers get small fixed corrections; other tokens
get a nearly zero background response. The last 300 characters of context
are retained, resetting at each document boundary.
"""
import re
from wordfreq import zipf_frequency

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        past, count = '', 0
    else:
        _, past, count = carry
    s = prefix.token_strings[-1]
    value = -0.003
    if count == 0:
        value = -0.13
        if s.lstrip().startswith('//'):
            value = 3.21 if s.endswith('\n') else (1.3 if s.startswith(' ') else 1.8)
        elif s.lstrip().startswith(('/*', '"""', "'''")):
            value = 0.6
        elif s.strip() in {'#', '##'}:
            value = 0.55
    elif s == '//' and past.strip() == '//':
        value = 1.12

    if s == 'Posts':
        if 'Joined:' in past[-110:]:
            value = 1.9
            if re.search(r'Joined:\s+[A-Za-z]', past[-110:]):
                value = 1.05
        elif 'Join Date' in past[-110:]:
            value = 0.6
        else:
            value = 0.1
    elif s == ' Posts':
        value = 0.35 if ('Joined:' in past or 'Recommended' in past[-30:]) else 0.0
    elif s == 'Views' and 'Repl' in past[-100:]:
        value = 1.6
    elif s == ' Reply':
        if past.rstrip().endswith('«'):
            value = 4.7
        elif past.endswith('Leave a'):
            value = 3.55
        elif 'message' in past[-70:] or past.endswith('Expert'):
            value = 1.7
        elif re.search(r'[,.(]\s*$', past):
            value = 0.0
        else:
            value = 1.0
    elif s == 'Reply':
        value = 3.5 if past.endswith('\n') else 0.0
    elif s == ' reply' and 'Login to' in past[-30:]:
        value = 1.1
    elif s == ' Replies':
        value = 1.6 if re.search(r'(\d|#{2,})\s*$', past) else 0.3
    elif s == ' replies':
        value = 2.2 if re.search(r'\d$', past) else -0.2
        if re.search(r'Show \d+$', past):
            value = 4.4
    elif s == ' Pages' and re.search(r'Words: \d+ -$', past):
        value = 3.4
    elif s == 'Share' and past.endswith('Slide'):
        value = 3.56 if past.endswith('Upcoming Slide') else 2.4
    elif s == 'Joined':
        value = 0.6 if 'Math Expert' in past[-30:] else 0.2
    elif s == 'udos' and past.endswith('K'):
        value = 1.0 if 'Followers:' in past[-100:] else -0.27
    elif s == ' views' and re.search(r'\d\s*$', past):
        value = -0.28
        if re.search(r'Answers? \d+$', past):
            value = 2.1
        elif re.search(r'answers? \d+$', past):
            value = 0.6
    elif s in {' vote', ' votes'}:
        value = -0.15
        if past.endswith('Sign up to'):
            value = 2.2
        elif re.search(r'(?:\.\.\.|…|•)[^\n]{0,100}\d+$', past):
            value = 1.0
    elif s in {'Likes', ' Likes'} and re.search(r'\d\s*$', past):
        value = 1.7 if s == 'Likes' else 1.1
    elif s == ' Pages' and re.search(r'(?:^|\n|• )\d+$', past):
        value = 0.8
    elif s == 'Related' and past.endswith('\n'):
        value = 1.5 if 'Answers and Replies' in past[-60:] else 0.6
    elif s in {'Continue', ' Continue'} and past.rstrip().endswith('…'):
        value = 1.3 if s.startswith(' ') else 0.65
    elif s in {' content', ' Content'} and past.lower().endswith('skip to'):
        value = 1.0
    elif s == 'Worksheet' and past.endswith('Math\n'):
        value = 0.65
    elif s == ' Level' and past.endswith('Challenge'):
        value = 0.14
    elif s == ' More' and past.endswith('(View'):
        value = -0.3

    if s == '<think>':
        value = 0.29
    elif s == '<tool_call>':
        value = -0.14
    if s in {' ,', ' )', ' .'}:
        value = -0.03
        if re.search(r'(?:\b\d+|\b[A-Za-z])$', past):
            value = -0.3 if s == ' ,' else (-0.2 if s == ' )' else -0.13)
        if re.search(r'(?:^|\s)[a-zA-Z]$', past):
            value = -0.8 if s in {' ,', ' )'} else -0.3
            if s == ' )' and re.search(r'\(\s*[A-Za-z]$', past):
                value = -1.4

    # Recognize a word printed one letter at a time (often from OCR).
    if s.isspace() or (len(s.strip()) == 1 and s.strip().isascii()):
        text = past if s.isspace() else past + s
        run = re.search(r'(?:^|\s)([A-Za-z](?: +[A-Za-z]){2,})$', text)
        if run and zipf_frequency(''.join(run[1].split()), 'en') >= 4.0:
            value = -0.8
        elif re.search(r'(?:^|\s)o f$', text):
            value = -0.8

    return (doc, (past + s)[-300:], count + 1), value

"""Mostly a detector for the token 同 ('same'), not sameness in general.

An isolated 同 is strongest, particularly in Japanese; merged compounds are
weaker. Related Chinese comparison words, 童 ('child', also read tong), and
several cross-language forms respond too. Korean motion/activity compounds
and Vietnamese community/similarity compounds attenuate it. Thai ต่าง
('different') is recognized when its final subword follows ต. The character
票 ('ticket') is a secondary trigger. Other tokens are predicted as zero.
"""
import regex

READS = ()
KANA = regex.compile(r'[\p{Script=Hiragana}\p{Script=Katakana}]')
# Stems of motion/activity compounds: movement, exercise, operation, action,
# activity, vibration, labor, automatic, and manual.
MOTION_STEMS = ('이', '운', '작', '행', '활', '진', '노', '자', '수')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        recent, tail = '', b''
    else:
        _, recent, tail = carry
    raw = prefix.token_bytes[-1]
    token = prefix.token_strings[-1].strip()
    # A split character counts only when this token actually completes it.
    if token == '\ufffd':
        for ch in ('同', '童'):
            if (tail + raw).endswith(ch.encode('utf-8')):
                token = ch

    value = 0.0
    if token == '同':
        value = -7.7 if KANA.search(recent) else -5.6
        if recent.endswith('非'):
            value = -9.3
    elif token == '童':
        value = -6.1
    elif '同' in token:
        if token.endswith('合同'):
            value = -3.9
        elif token.startswith('同一'):
            value = 0.5
        elif token.endswith(('同学', '同學')):
            value = -3.1
        elif token.endswith('不同') and len(token) <= 3:
            value = -3.1
        elif token in ('协同', '協同', '会同', '會同'):
            value = -2.9
        elif token in ('不同的', '不同于', '不同於', '同意'):
            value = -1.8
        elif token.endswith('同') and len(token) == 2:
            value = -1.8
        elif token.endswith(('同学们', '同學們')):
            value = -1.3
        else:
            value = -0.5
    elif token in ('儿童', '兒童'):
        value = -1.7
    elif token == '異':
        value = -1.8
    elif token == '异':
        value = -1.0
    elif token in ('铜', '銅', '桐'):
        # Other tong characters: copper and paulownia.
        value = -1.9
    elif token in ('不一样', '不一樣'):
        value = -3.1
    elif token in ('不一样的', '不一樣的'):
        value = -1.8
    elif token in ('一样', '一樣'):
        value = -0.4
    elif token == '票':
        value = -2.1
    elif token == '동':
        if raw.startswith(b' '):
            value = -4.9
        else:
            value = -0.3 if recent.endswith(MOTION_STEMS) else -3.1
    elif token == 'đồng':
        value = -2.7 if recent.endswith(('cộng', 'tương')) else -6.5
    elif token == 'cùng':
        value = -1.2
    elif token == 'Tong':
        value = -2.5
    elif token == '่าง' and recent.endswith('ต'):
        value = -5.9

    recent = (recent + prefix.token_strings[-1])[-80:]
    return (doc, recent, (tail + raw)[-3:]), value

programs.haiku:
"""Sameness / togetherness morpheme 同 (tóng, 'same, together') and its sound-alikes in
Chinese, Japanese, Korean and Vietnamese text. The program scores each token by how much
its 同 means 'together, agreed, alike': the bare character is strongest, compounds such as
不同, 共同, 合同, 同学 are medium, 'at the same time' words (同时, 同样) are weak, and
同一 ('one and the same') is slightly positive. 異/异 ('different') is medium."""
READS = ()
BARE = ("同", "童", "铜", "桐", "동", "đồng", "ồng")
SAME_TIME = ("同时", "同样", "同步", "同事", "同行", "同期", "同比", "同じ", "同時")
def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    if tok in BARE:
        return None, -6.0
    if tok in ("異", "异", "cùng", "Cùng"):
        return None, -1.3
    if tok == "동":
        return None, -3.6
    if "同一" in tok:
        return None, 0.3
    if any(c in tok for c in "同童동铜桐") or "đồng" in tok:
        if any(m in tok for m in SAME_TIME):
            return None, -0.4
        return None, -2.5
    return None, 0.0

programs.sol:
"""A token-boundary-sensitive detector for pole/polar and 'extreme'.

It fires most strongly when a token completes pole or polar, or the Han
character 极/極. Whole-token compounds are weaker or silent. Smaller rules
cover related pol syllables, Greek/Cyrillic spellings, and negative por
spellings. Only a short byte suffix is kept, reset for each document.
"""
READS = ()


def spelling(previous, token):
    s = token.lower()
    word = s.strip()
    if word in ('pole', 'poles'):
        return 5.6
    if word == 'polar':
        return 5.2
    if word == 'polarity':
        return 3.6
    if word == 'bipolar':
        return 3.8
    if word.startswith('polariz'):
        return 1.6
    if s and s[0].isalpha():
        if previous.endswith('p'):
            if s == 'olar':
                return 8.8
            if s in ('olarity', 'olars'):
                return 3.9
            if s in ('ole', 'oles'):
                return 6.5
            if s in ('ol', 'ola', 'oli', 'olo', 'olis'):
                return 2.0
            if s.startswith(('erg', 'urg', 'orc', 'orm', 'ork')):
                return -2.8
            if s == 'err':
                return -1.3
        if previous.endswith('polar') and s == 'ities':
            return 5.0
        if previous.endswith('por') and s in ('c', 'ci'):
            return -3.0
    if word == 'por':
        return -1.3 if token.strip()[0].isupper() else -0.55
    if word in ('porch', 'pork', 'perg'):
        return -1.6
    # Field/pole syllables in Cyrillic and Greek.
    if s in ('λ', 'ль') and previous.endswith(('πο', 'πό', 'по')):
        return 3.4
    if s == 'оль' and previous.endswith('п'):
        return 2.8
    if previous.endswith('пол') and s in ('е', 'ем', 'ей', 'ев', 'ю'):
        return 3.5 if s != 'ю' else 5.8
    if token == 'пол':
        return 1.1
    if word == 'поля':
        return 1.8
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = b'' if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_bytes[-1]
    joined = old + raw
    token = raw.decode('utf-8', 'ignore')
    previous = old.decode('utf-8', 'ignore').lower()
    value = spelling(previous, token)
    # Recognize a singleton character even when its UTF-8 bytes are split.
    for char in '极極극':
        encoded = char.encode()
        start = joined.rfind(encoded)
        end = start + len(encoded)
        if start >= 0 and end > len(old) and len(token.strip()) <= 1:
            value = 7.8 if char == '极' else 6.8
            if char == '극' and encoded not in raw:
                value = 10.0
            break
    if token in ('积极', '積極'):
        value = 1.9
    elif len(token) == 2 and token[0] == '极' and token[1] in '为其大':
        value = 3.0
    elif token.strip() == 'rất':
        value = 2.6
    return (doc, joined[-32:]), value

programs.haiku:
"""Draft 4: the pieces that spell 'polar' / 'pole' (a word-level concept: magnetic or
electric poles, polarity, polarization), the single CJK/Hangul character meaning
'pole, extreme' (极, 極, 극), and a weak negative for the Spanish/Portuguese word 'por'.
Each piece fires with its typical activation; all other tokens are 0."""
READS = ()

# Pieces of the English word 'pole' / 'polar' and their typical activation.
POLE_PIECES = {
    "pole": 5.9, "poles": 5.9, "polar": 5.3, "polarity": 4.3, "bipolar": 3.3,
    "olar": 4.1, "olars": 1.7, "oles": 2.1, "ole": 0.5,
    "olarity": 2.8, "polarization": 1.6,
}
# Single characters meaning 'pole' or 'extreme' in Chinese, Japanese and Korean.
POLE_CHARS = {"极": 7.5, "極": 7.2, "극": 7.6}
# The Spanish/Portuguese word 'por' ('by', 'for') is mildly negative.
POR_WORDS = {"por": -0.6}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in POLE_CHARS:
        return None, POLE_CHARS[token]
    word = token.strip().lower()
    if word in POLE_PIECES:
        return None, POLE_PIECES[word]
    if word in POR_WORDS:
        return None, POR_WORDS[word]
    return None, 0.0

programs.sol:
"""Score line breaks that look like the end of a title or section heading.

Headings are often early in a document, capitalized, lightly punctuated,
and separated from prose by a blank line or a completed sentence. Lower-case
and heavily punctuated lines usually have little signal. Abbreviations are
weaker than mixed-case titles. Escaped newlines count too. A separate rule
recognizes the .com ending of GitHub source-hosting domains.
"""
import re

READS = ()
WORDS = re.compile(r'[^\W\d_]+')


def heading_value(line, previous, line_number, last_token):
    text = line.strip()
    words = WORDS.findall(text)
    n = len(words)
    capitals = sum(w[0].isupper() for w in words) / max(1, n)
    letters = sum(c.isalpha() for c in text)
    upper = sum(c.isupper() for c in text) / max(1, letters)
    punctuation = sum(not c.isalnum() and not c.isspace() for c in text)
    punctuation /= max(1, len(text))
    ascii_fraction = sum(c.isascii() for c in text) / max(1, len(text))
    ends_word = bool(text and text[-1].isalnum())
    phrase = text.rstrip(')]}”’\'"?!')
    ends_phrase = bool(phrase and phrase[-1].isalnum())
    blank = not previous.strip()
    markdown = bool(re.match(r'^#+\s', text))
    short_upper = upper if n < 3 else 0.0

    if capitals * ends_phrase <= 0.392:
        if upper * ends_word <= 0.007:
            if ascii_fraction <= 0.712:
                if not ends_word:
                    return 0.060 if len(text) <= 17 else -0.009
                return 0.318 if line_number <= 5 else 0.115
            if not blank:
                return -0.028 if punctuation <= 0.140 else 0.0
            return 0.227 if markdown else 0.009
        if punctuation <= 0.003:
            if line_number <= 6:
                return 0.824 if blank else 0.328
            return 0.189 if n <= 7 else 0.014
        if line_number <= 1:
            return 0.301 if n <= 21 else 0.027
        return 0.283 if markdown else 0.018

    if not blank:
        if re.search(r'[.!?:]\s*$', previous):
            if punctuation <= 0.073:
                short_capital_word = n < 3 and words[-1][0].isupper()
                return 0.202 if short_capital_word else 0.561
            return 0.192 if line_number <= 5 else 0.044
        if punctuation <= 0.049:
            return 0.243 if short_upper <= 0.093 else 0.097
        return 0.135 if line_number <= 3 else 0.016
    if punctuation <= 0.061:
        if line_number <= 5:
            return 0.816 if short_upper <= 0.174 else 0.392
        return 0.226 if len(last_token.strip()) <= 3 else 0.533
    if markdown:
        return 0.445 if len(last_token.strip()) <= 4 else 0.651
    return 0.222 if punctuation <= 0.102 else 0.079


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, previous, line_number, last_token = '', '', 0, ''
    else:
        _, line, previous, line_number, last_token = carry
    raw = prefix.token_strings[-1]
    token = raw.replace('\\n', '\n')
    value = -0.003
    if raw == '.com':
        source_host = line.lower().endswith(('github', 'githubusercontent'))
        value = 1.35 if source_host else -0.08
    if token in {'<|endoftext|>', '<|im_start|>'}:
        line, previous, line_number = '', '', 0
    elif '\n' in token:
        before = token.split('\n', 1)[0]
        value = heading_value(line + before, previous, line_number, last_token)
        if (line + before).strip():
            line_number += 1
        previous = (line + token).split('\n')[-2]
        line = token.rsplit('\n', 1)[-1]
    else:
        line = (line + token)[-1500:]
    return (doc, line, previous, line_number, raw), float(value)

"""Predict a spelling-sensitive AMID/AMONG feature.

Negative rules cover amid(st), among(st), midst, parmi, and split M+ID
spellings, including amide compounds and Latin transliterations. Split
completions are often stronger than whole tokens. Camel-case boundaries
block the M+ID rule. Encirclement verbs followed by 'by' are negative too.
Secondary positive rules cover yaw and split Y+AW, Y+EW, and M+AW.

Only the unfinished word is remembered; document boundaries reset it.
Other positions get zero, omitting many rare token-specific responses.
"""
import re
from anyascii import anyascii

READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    match = re.search(r'[^\W\d_]+$', old + token)
    word = match.group()[-48:] if match else ''
    previous = anyascii(old).lower()
    current = anyascii(token).lower()
    bare = current.strip()
    continuation = bool(token and token[0].isalpha() and old)
    # Capitalization starts a new segment in identifiers such as streamID.
    if continuation and token[0].isupper() and old[-1].islower():
        continuation = False
    value = 0.0

    if bare in {'amid', 'amidst'}:
        value = -12.2
    elif bare == 'amongst':
        value = -5.0
    elif bare == 'among':
        value = -3.0
    elif bare == 'midst':
        value = -3.4
    elif bare == 'mid':
        value = -1.2
    elif (previous == 'par' and current == 'mi') or bare == 'parmi':
        value = -8.5
    elif continuation and current == 'st':
        if previous == 'amid':
            value = -15.0
        elif previous == 'among':
            value = -12.0
    elif continuation and previous.endswith('am') and current == 'ong':
        value = -12.0
    elif bare == 'mong' and continuation:
        value = -6.0
    elif bare == 'amide':
        value = -6.0
    elif (continuation and previous.endswith('m')
          and current.startswith('id')):
        value = -3.2
        if previous.endswith('am'):
            value = -10.5 if current == 'id' else -7.5
            if old == 'Am' and current == 'id':
                value = -17.0
        elif previous.endswith('asm'):
            value = -1.5
        elif current.startswith('iddle'):
            value = -1.2
    elif bare == 'yaw' or (previous == 'yaw' and current == 'ing'):
        value = 4.8
    elif continuation and current in {'aw', 'ew'}:
        if previous.endswith('y'):
            value = 8.0 if current == 'aw' else 4.5
        elif previous.endswith('m') and current == 'aw':
            value = 4.8
    elif bare == 'by':
        if previous in {'surrounded', 'flanked'}:
            value = -4.3
        elif previous == 'accompanied':
            value = -0.8

    return (doc, word), value

"""Sparse approximation using document openings and numeral spelling.

Opening comment markers, car/create/commuting fragments, whitespace,
initials, and digits receive fixed, class-specific values. Repetitions of
an opening token retain its value. Within longer numerals, a digit after
an interior 1 is usually positive; the estimate decreases with that digit.
Middle-dot fillers are negative. All other positions receive zero.
These surface rules explain only a small part of the component's variation.
"""

READS = ()


def initial_value(text):
    word = text.strip()
    if text == '//\n':
        return -2.03
    if text == '//':
        return 0.336
    if word == '--':
        return 1.223
    if word.lower() == 'car':
        return 1.068 + 0.41 * word.istitle() - 0.117 * text.startswith(' ')
    if text == 'create':
        return 1.422
    if text == ' commuting':
        return 1.127
    if text == '<|endoftext|>':
        return 1.275
    if text == ' ':
        return -0.317
    if text == '\r':
        return 0.81
    if text == '\t' or text.lstrip(' ') == '\n\n':
        return 0.37
    if text == '\n':
        return -0.15
    if len(text) == 1 and '0' <= text <= '9':
        return 0.291 if text == '0' else -0.105
    if len(word) == 1 and word.isascii() and word.isupper():
        return -0.40
    return 0.0


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    digit = len(text) == 1 and '0' <= text <= '9'
    if carry is None or carry[0] != doc:
        value = initial_value(text)
        previous_digits = ''
        first_text, first_value, repeating = text, value, True
    else:
        _, first_text, first_value, repeating, previous_digits = carry
        repeating = repeating and text == first_text
        value = first_value if repeating else 0.0
        if not repeating and digit and len(previous_digits) >= 2:
            if previous_digits[-1] == '1':
                value = 0.275 - 0.022 * int(text) + 0.020 * (text == '0')
                value += 0.035 * (previous_digits[-2] == '0')
                if len(previous_digits) >= 4:
                    value -= 0.085
    if len(text) >= 2 and all(c == '·' for c in text):
        value = -0.466
    digits = (previous_digits + text)[-16:] if digit else ''
    return (doc, first_text, first_value, repeating, digits), value

"""A local spelling-boundary approximation, not a semantic word classifier.

The strongest Latin pattern is an i/c/h continuation after n, especially
in consonant+n clusters. Some other n-continuations have the opposite
sign; ni+ch-like spellings also get a negative correction in Latin and
Cyrillic. Additional rules cover Vietnamese nh spellings and
person-radical Han characters read
'hou', dot separators, and document-initial positions. The rules deliberately
omit most token-specific and longer-context variation in the amplitudes.
"""
import unicodedata
import regex
import unihan
from pypinyin import lazy_pinyin

READS = ()


def step(carry, prefix, upstream):
    t = prefix.position
    start = t == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    prev = '' if start else prefix.token_strings[-2]
    prevstart = not start and (t == 1 or
        prefix.document_ids[-2] != prefix.document_ids[-3])
    cur = prefix.token_strings[-1]
    p, s = prev.lower(), cur.lower()
    value = 0.104 if start else -0.0024

    if p.endswith('n'):
        if s.startswith('i'):
            value -= 0.05
            if len(p.strip()) == 1:
                value -= 0.25
            if prevstart:
                value -= 0.4
            if s.startswith('ic'):
                value -= 0.33
                if s.startswith('ich'):
                    value -= 3.35
                if s.startswith('ice'):
                    value -= 2.45
                if (len(p) > 1 and p[-2] in 'bcdfghjklmnpqrstvwxyz'
                        and s.startswith(('ich', 'ice', 'ici'))):
                    value -= 1.55
            if s.startswith('icious'):
                value = -7.3
            if s.startswith('inja'):
                value = 3.2
        elif s.startswith('rich'):
            value -= 0.8
        elif s.startswith('och'):
            value -= 0.85
        elif s.startswith('px'):
            value += 2.0
        elif s.startswith('pm'):
            value += 0.7
        elif s.startswith('ja'):
            value += 2.0 if p.endswith('in') else 0.3
        elif s.startswith('h') and len(s) <= 2:
            value += 3.5 if p.strip() == 'n' and s == 'ho' else 0.25
        elif cur in ('°', 'º'):
            value += 3.8 if cur == '°' else 0.8
    if p.endswith(('ni', 'ни')) and s.startswith(('č', 'ch', 'ч', 'ц')):
        value -= 1.0
    if p.endswith('i') and s.startswith('hi'):
        value -= 0.4
    if prev.endswith('NI') and cur == 'H':
        value -= 1.9
    if prev.endswith('N') and cur == 'H':
        value += 0.45
    if prev.endswith('N') and cur == 'Ac':
        value += 1.0

    word = s.strip()
    if word.startswith('nh') and s.startswith(' '):
        value += 0.1
        if word == 'nh':
            value += 0.6
        if any(c in unicodedata.normalize('NFD', word) for c in '\u0300\u0301'):
            value += 1.5
        if word == 'nhà':
            value += 4.0
    if cur == 'Nh':
        value += 1.8
    if len(cur) == 1 and regex.fullmatch(r'\p{Script=Han}', cur):
        if unihan.radical(cur) == 9 and lazy_pinyin(cur) == ['hou']:
            value -= 5.0
    if cur and set(cur) == {'·'}:
        value += 0.95
    if prevstart and prev == 'Title' and cur == ':':
        value += 2.0
    return None, value

