"""Layer 1, MLP down-projection, component 4863: a mostly lexical component.

What it does, in plain terms: it is near zero on almost every token, and fires hard on a
few word fragments and characters:

* Negative on the "-ich" sound inside names and foreign words (Voynich, Bernice, Shuichi,
  Nicholas-style "Nich", "niche", "Hiroshi"-like "hiro"/"chio"): strongly negative.
  The plainer spellings "ich", "ice", "iche", "rich", "icio" are only mildly negative.
* Negative on the Chinese marquis characters 侯 and 候 (hou).
* Positive on the Vietnamese word "nhà" (house), strongly; on other Vietnamese "nh-"
  words (nhạc, nhờ, nhớ) weakly.
* Positive on a run of middle dots "··" and on a capitalised first word of a document.

Everything else is predicted as 0. The values are rough group averages taken from
training rows, not fitted to eval. Context (what precedes the fragment) matters a lot and
is not modelled, so most of the variance stays unexplained.
"""

READS = ()

# Name-internal "ich/niche/Nich/ichi/chio/hiro" fragments: strongly negative.
NAME_FRAGMENTS = {"ichi", "niche", " niche", "Nich", " Nich", " nich", "nich", "chio", "hiro"}
# Plain "ich"-spelled fragments inside a word (no leading space): mildly negative.
ICH_FRAGMENTS = {"ich", "iche", "ice", "icio", "icious", "icia", "ici", "rich", "ices"}
MARQUIS_CHARS = {"侯", "候"}
HOUSE = {" nhà"}
NH_WORDS = {" nhạc", " nhờ", " nhớ", "Nh", " nh", "nh", " nhé"}
DOTS = {"··"}


def _is_capitalised_word(token):
    return len(token) > 1 and token[0].isupper() and token[1:].islower() and token.isalpha()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    # A document's first token: the row's start, or the first token after a document change.
    first_in_document = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]

    if token in NAME_FRAGMENTS:
        value = -1.6
    elif token in MARQUIS_CHARS:
        value = -5.0
    elif token in HOUSE:
        value = 5.5
    elif token in DOTS:
        value = 0.9
    elif token in NH_WORDS:
        value = 1.2
    elif token in ICH_FRAGMENTS:
        value = -0.35
    elif first_in_document and _is_capitalised_word(token):
        value = 0.4
    else:
        value = 0.0
    return carry, float(value)
